const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:37,000", "arabic": "لَنْ يَجِدَ أَمِيرُ الْمُؤْمِنِينَ خَيْرًا مِنْكَ لِتَحْمِلَ هَذِهِ الْمَسْؤُولِيَّةَ، غَفَرَ اللَّهُ لَكَ", "segs": null, "full_uz": "Amir al-Mo'minin bu mas'uliyatni ko'tarish uchun sizdan yaxshirog'ini topmaydi. Alloh sizni kechirsin.", "note": null},
  {"num": 4, "time": "00:00:37,640 --> 00:00:43,000", "arabic": "إِنَّمَا جِئْتُ لِأَقْتَبِسَ مِنْكَ الْعِلْمَ وَأَنْتَ تَأْمُرُنِي أَنْ أَرْحَلَ عَنْكَ لِأَتَوَلَّى الْقَضَاءَ", "segs": [{"ar": "إِنَّمَا جِئْتُ لِأَقْتَبِسَ مِنْكَ الْعِلْمَ", "uz": "Men sizdan ilm olgani kelgan edim"}, {"ar": "وَأَنْتَ تَأْمُرُنِي أَنْ أَرْحَلَ عَنْكَ لِأَتَوَلَّى الْقَضَاءَ", "uz": "siz esa meni qozilikni egallash uchun sizdan uzoqlashishga buyuryapsiz"}], "full_uz": "Men sizdan ilm olgani kelgan edim, siz esa meni qozilikni egallash uchun sizdan uzoqlashishga buyuryapsiz.", "note": null},
  {"num": 6, "time": "00:00:43,920 --> 00:00:54,039", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، يَا أَبَا عَبْدِ اللَّهِ، إِنْ سَمِعْتُ هَذَا مِنْكَ لَنْ تَرَانِي ثَانِيَةً", "segs": null, "full_uz": "La havla va la quvvata illa billah. Abu Abdulloh, sizdan buni yana eshitsam, meni ikkinchi marta ko'rmaysiz.", "note": null},
  {"num": 9, "time": "00:00:54,039 --> 00:01:03,280", "arabic": "أَرَأَيْتَ إِلَى أَيْنَ وَصَلَتْ بِنَا الْأُمُورُ يَا أَبَا الْعَبَّاسِ؟ صِرْنَا نُقَاتِلُ بَعْضُنَا بَعْضًا", "segs": null, "full_uz": "Ko'rdingizmi, ishlarimiz qayerga yetib bordi, Abu al-Abbos? Bir-birimizni o'ldirishga aylanib qoldik.", "note": null},
  {"num": 11, "time": "00:01:03,280 --> 00:01:13,680", "arabic": "أَثَمَّ شَرٌّ أَكْبَرُ مِنْ أَنْ يَتَقَاتَلَ الْمُسْلِمُونَ فِيمَا بَيْنَهُمْ تَارِكِينَ أَعْدَاءَهُمْ عَلَى الثُّغُورِ تَشْمَتُ بِهِمْ وَتَسْخَرُ مِنْ جَهَالَاتِهِمْ", "segs": [{"ar": "أَثَمَّ شَرٌّ أَكْبَرُ مِنْ أَنْ يَتَقَاتَلَ الْمُسْلِمُونَ فِيمَا بَيْنَهُمْ", "uz": "Musulmonlar bir-biriga qarshi urushishidan katta yovuzlik bormi"}, {"ar": "تَارِكِينَ أَعْدَاءَهُمْ عَلَى الثُّغُورِ تَشْمَتُ بِهِمْ وَتَسْخَرُ مِنْ جَهَالَاتِهِمْ", "uz": "dushmanlarini chegara postlarida qoldirib, dushmanlar esa ularning ustidan kulib, jaholatlarini masxara qilib turibdi"}], "full_uz": "Musulmonlar dushmanlarini chegara postlarida qoldirib, bir-biriga qarshi urushishidan katta yovuzlik bormi — dushmanlar esa ularning ustidan kulib, jaholatlarini masxara qilib turibdi.", "note": null},
  {"num": 13, "time": "00:01:13,680 --> 00:01:20,180", "arabic": "قَاتَلَ اللَّهُ مَنْ أَشْعَلَهَا يَا مَوْلَايَ، نَحْنُ مَا ذَهَبْنَا إِلَيْهِمْ", "segs": null, "full_uz": "Alloh uni yoqqan kishini halok qilsin, xo'jayinim — biz ularga bormadik.", "note": null},
  {"num": 15, "time": "00:01:20,180 --> 00:01:29,960", "arabic": "بَلْ هُمْ أَرَادُوهَا حَرْبًا نُقْتَلُ فِيهَا جَمِيعًا، لَيْسَ مُهِمًّا مَنْ أَشْعَلَهَا يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Balki ular buni hammamiz o'ladigan urush qilishni istashgan. Uni kim yoqqani muhim emas, Abu al-Abbos.", "note": null},
  {"num": 17, "time": "00:01:29,959 --> 00:01:34,780", "arabic": "اَلْمُهِمُّ أَنَّهَا حَرْبٌ سَتَجُزُّ رِقَابَنَا جَمِيعًا", "segs": null, "full_uz": "Muhimi — bu bizning hammamizning bo'ynimizni kesadigan urushdir.", "note": null},
  {"num": 18, "time": "00:01:34,780 --> 00:01:54,479", "arabic": "كَيْفَ حَدَثَ ذَلِكَ؟ لَا أَدْرِي يَا مَوْلَايَ لَا أَدْرِي", "segs": null, "full_uz": "Bu qanday sodir bo'ldi? Bilmayman, xo'jayinim, bilmayman.", "note": null},
  {"num": 20, "time": "00:01:54,480 --> 00:02:02,560", "arabic": "يَا غُلَامُ، أَيَسْتَطِيعُ طَاهِرُ بْنُ الْحُسَيْنِ قَتْلَ ابْنِ مَاهَانَ وَتَمْزِيقَ جُنْدِهِ؟ هَذَا مَا حَدَثَ يَا مَوْلَايَ هَذَا مَا حَدَثَ", "segs": null, "full_uz": "Ey bola, Tohir ibn al-Husayn Ibn Mohanni o'ldirib, uning qo'shinini parchalab tashlay oladimi? Bo'lgani shu, xo'jayinim, bo'lgani shu.", "note": null},
  {"num": 22, "time": "00:02:02,560 --> 00:02:14,560", "arabic": "يَا لِلْخِذْلَانِ، أَرْبَعَةُ آلَافِ مَارِقٍ يَنْتَصِرُونَ عَلَى أَرْبَعِينَ أَلْفًا مِنْ خِيرَةِ جُنُودِنَا، أَيُّ خِذْلَانٍ هَذَا؟ أَيُّ خِذْلَانٍ هَذَا؟", "segs": [{"ar": "يَا لِلْخِذْلَانِ، أَرْبَعَةُ آلَافِ مَارِقٍ يَنْتَصِرُونَ عَلَى أَرْبَعِينَ أَلْفًا مِنْ خِيرَةِ جُنُودِنَا", "uz": "Bu qanday xor bo'lish — to'rt ming yo'ldan chiqqan, qirq mingdan iborat eng sara qo'shinimizni yengib qo'yishmoqda"}, {"ar": "أَيُّ خِذْلَانٍ هَذَا؟ أَيُّ خِذْلَانٍ هَذَا؟", "uz": "Bu qanday sharmandalik? Bu qanday sharmandalik?"}], "full_uz": "Bu qanday xor bo'lish — to'rt ming yo'ldan chiqqan, o'ttiz qirq mingdan iborat eng sara qo'shinimizni yengib qo'yishmoqda! Bu qanday sharmandalik? Bu qanday sharmandalik?", "note": null},
  {"num": 24, "time": "00:02:16,819 --> 00:02:26,780", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي هَزَمَ أَعْدَاءَكَ وَنَصَرَ جُنْدَكَ يَا أَمِيرَ الْمُؤْمِنِينَ، وَأَرَاكَ مَا تُحِبُّ مِنْ خَادِمِكَ وَقَائِدِ جُنْدِكَ الطَّاهِرِ بْنِ الْحُسَيْنِ", "segs": [{"ar": "اَلْحَمْدُ لِلَّهِ الَّذِي هَزَمَ أَعْدَاءَكَ وَنَصَرَ جُنْدَكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "uz": "Dushmanlaringizni yengib, qo'shiningizga g'alaba bergan Allohga hamd bo'lsin, Amir al-Mo'minin"}, {"ar": "وَأَرَاكَ مَا تُحِبُّ مِنْ خَادِمِكَ وَقَائِدِ جُنْدِكَ الطَّاهِرِ بْنِ الْحُسَيْنِ", "uz": "xizmatkoringiz va qo'shin sarkardangiz Tohir ibn al-Husayn orqali xohlaganingizni ko'rsatdi"}], "full_uz": "Dushmanlaringizni yengib, qo'shiningizga g'alaba bergan Allohga hamd bo'lsin, Amir al-Mo'minin — xizmatkoringiz va qo'shin sarkardangiz Tohir ibn al-Husayn orqali xohlaganingizni ko'rsatdi.", "note": null},
  {"num": 26, "time": "00:02:26,780 --> 00:02:38,700", "arabic": "بَارَكَ اللَّهُ فِيكُمْ يَا أَخْوَالَ أَمِيرِ الْمُؤْمِنِينَ، لَوْلَا فَضْلُ اللَّهِ ثُمَّ وَفَاؤُكُمْ وَشَجَاعَتُكُمْ لَمَا كَانَ لِهَذَا النَّصْرِ أَنْ يَكُونَ", "segs": null, "full_uz": "Alloh sizlarga barakot bersin, Amir al-Mo'mininning tog'alari — Allohning fazli, so'ng sizlarning sadoqat va jasoratingiz bo'lmaganida, bu g'alaba ham bo'lmasdi.", "note": null},
  {"num": 29, "time": "00:02:38,700 --> 00:02:46,000", "arabic": "إِنَّ مَقْتَلَ الْإِبْنَاوِيِّ بَعْدَ ابْنِ مَاهَانَ سَيُهِنُ عَزْمَ أَهْلِ بَغْدَادَ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Ibn Mohandan keyin al-Ibnaviyning ham o'ldirilishi, Alloh xohlasa, Bag'dod ahlining qat'iyatini yumshatadi.", "note": null},
  {"num": 31, "time": "00:02:46,000 --> 00:02:52,340", "arabic": "لَعَلَّهُمْ يَعُودُونَ عَنْ غَيِّهِمْ وَطُغْيَانِهِمْ، إِنْ عَادُوا عُدْنَا يَا مَوْلَايَ", "segs": null, "full_uz": "Balki ular adashuv va tug'yonlaridan qaytishar. Agar ular qaytsa, biz ham qaytamiz, xo'jayinim.", "note": null},
  {"num": 33, "time": "00:02:52,340 --> 00:02:58,060", "arabic": "وَلَنْ يَعُودُوا إِلَّا لِهَزِيمَتِهِمْ، وَنَحْنُ إِلَى الْمَصِيرِ دَوْمًا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Ular faqat mag'lubiyatlaridan keyin qaytishadi — biz esa, Alloh xohlasa, doim g'alabaga eltuvchi yo'ldamiz.", "note": null},
  {"num": 35, "time": "00:02:58,060 --> 00:03:08,200", "arabic": "تُرَى كَمْ قُتِلَ مِنَ الْمُسْلِمِينَ فِي هَذِهِ الْحَرْبِ؟", "segs": null, "full_uz": "Qiziq, bu urushda qancha musulmon o'ldirildi ekan?", "note": null},
  {"num": 36, "time": "00:03:08,200 --> 00:03:17,640", "arabic": "هَذَا مَا أَرَدْتَهُ يَا ابْنَ أَبِي، أَمَا كَانَ لَكَ فِي الْوَفَاءِ بِعَهْدِ أَبِي كَلَامٌ دُوحَةٌ عَنْ كُلِّ ذَلِكَ؟", "segs": null, "full_uz": "Bu — otamning o'g'li, sen istagan narsang edi. Otamning ahdiga vafo qilishda bularning hammasidan yiroq bo'ladigan bir gaping bo'lmadimi?", "note": null},
  {"num": 38, "time": "00:03:17,639 --> 00:03:24,519", "arabic": "غَفَرَ اللَّهُ لَكَ يَا أَبَا مُوسَى وَغَفَرَ لَنَا جَمِيعًا", "segs": null, "full_uz": "Alloh sizni kechirsin, Abu Muso, va barchamizni kechirsin.", "note": null},
  {"num": 39, "time": "00:03:24,519 --> 00:03:29,719", "arabic": "لَا أَكْتُمُ كَسْرًا يَا حَارِثُ، إِنَّ الْأُمُورَ تَسِيرُ مِنْ سَيِّئٍ إِلَى أَسْوَأَ", "segs": null, "full_uz": "Sindirilganimni yashirmayman, Horis — ishlar yomondan battarga tomon ketmoqda.", "note": null},
  {"num": 41, "time": "00:03:29,719 --> 00:03:35,500", "arabic": "لَقَدِ اسْتَوْلَى طَاهِرُ بْنُ الْحُسَيْنِ عَلَى الْبَصْرَةِ بَعْدَ أَنْ أَحْكَمَ سَيْطَرَتَهُ عَلَى غَيْرِهَا مِنَ الْأَمْصَارِ", "segs": null, "full_uz": "Tohir ibn al-Husayn boshqa shaharlar ustidan nazoratini mustahkamlagandan so'ng, Basrani ham egallab oldi.", "note": null},
  {"num": 43, "time": "00:03:35,500 --> 00:03:38,839", "arabic": "وَأَخْشَى أَنْ نَرَاهُ بَعْدَ أَسَابِيعَ يَطْوِي بَغْدَادَ", "segs": null, "full_uz": "Va qo'rqamanki, bir necha haftadan so'ng u Bag'dodni ham egallab olishini ko'ramiz.", "note": null},
  {"num": 44, "time": "00:03:38,839 --> 00:03:43,239", "arabic": "كَيْفَ وَصَلَتِ الْأُمُورُ إِلَى هَذَا السُّوءِ؟ أَلَسْنَا أَكْثَرَ مِنْهُمْ عُدَّةً وَعَدَدًا؟", "segs": [{"ar": "كَيْفَ وَصَلَتِ الْأُمُورُ إِلَى هَذَا السُّوءِ؟", "uz": "Ishlar bunday yomonlikka qanday yetib bordi?"}, {"ar": "أَلَسْنَا أَكْثَرَ مِنْهُمْ عُدَّةً وَعَدَدًا؟", "uz": "Biz ulardan qurol-yarog' va sonda ko'p emasmizmi?"}], "full_uz": "Ishlar bunday yomonlikka qanday yetib bordi? Biz ulardan qurol-yarog' va sonda ko'p emasmizmi?", "note": null},
  {"num": 46, "time": "00:03:43,239 --> 00:03:47,239", "arabic": "كَيْفَ يَتَسَاقَطُ قَادَةُ أَمِيرِ الْمُؤْمِنِينَ الْوَاحِدُ تِلْوَ الْآخَرِ؟", "segs": null, "full_uz": "Amir al-Mo'mininning sarkardalari bir-birining ketidan qanday yiqilyapti?", "note": null},
  {"num": 47, "time": "00:03:47,639 --> 00:04:00,419", "arabic": "لَدَيْهِ الْوَلَاءُ الْمُطْلَقُ، إِنَّ جُنْدَهُ مُؤْمِنُونَ حَقَّ الْإِيمَانِ بِقَضِيَّتِهِمْ عَلَى الرَّغْمِ مِنْ فَسَادِهَا", "segs": null, "full_uz": "Unga mutlaq sodiqlik bor — uning qo'shini o'z ishiga chin dildan ishonadi, garchi u buzuq bo'lsa ham.", "note": null},
  {"num": 49, "time": "00:04:00,419 --> 00:04:09,719", "arabic": "إِنَّهُمْ يَعْلَمُونَ أَنَّ مَعْرَكَتَهُمْ مَعَنَا مَعْرَكَةُ حَيَاةٍ أَوْ مَوْتٍ، أَمَّا جُنْدُنَا تَعْسًا لِجُنْدِنَا", "segs": null, "full_uz": "Ular bilishadiki, biz bilan jangi hayot yoki o'lim jangidir. Bizning qo'shinimizga kelsak — bizning qo'shinimizga voy!", "note": null},
  {"num": 52, "time": "00:04:09,719 --> 00:04:17,960", "arabic": "إِنَّهُمْ لَا يَهْتَمُّونَ إِلَّا لِلنُّقُودِ الَّتِي يُغْدِقُهَا عَلَيْهِمْ أَبُو مُوسَى الْأَمِينُ بِدُونِ حِسَابٍ، تَعْسًا لَهُمْ", "segs": null, "full_uz": "Ular faqat Abu Muso al-Amin hisobsiz sochib berayotgan pulga qiziqishadi. Ularga voy!", "note": null},
  {"num": 54, "time": "00:04:17,960 --> 00:04:23,760", "arabic": "أَلَا يَعْلَمُونَ أَنَّ هَزِيمَتَنَا سَتَجْعَلُ الْمَأْمُونَ وَمَنْ مَعَهُ أَسْيَادًا عَلَيْنَا؟", "segs": null, "full_uz": "Mag'lubiyatimiz al-Ma'munni va uning odamlarini bizga hukmron qilishini bilishmaydimi?", "note": null},
  {"num": 56, "time": "00:04:23,760 --> 00:04:30,800", "arabic": "أَيُّ خِذْلَانٍ هَذَا؟ هُمْ عَبَدَةُ الْمَالِ، مَنْ يُعْطِي أَكْثَرَ يَشْتَرِي الْوَلَاءَ أَكْثَرَ", "segs": null, "full_uz": "Bu qanday xor bo'lish? Ular pulga sig'inuvchilar — ko'proq bergan ko'proq sodiqlikni sotib oladi.", "note": null},
  {"num": 59, "time": "00:04:30,800 --> 00:04:44,020", "arabic": "وَأَنْتَ لَمْ تَرَ الْخِذْلَانَ بَعْدُ، غَدًا عِنْدَمَا يَتَمَكَّنُ الْمَأْمُونُ وَمَنْ مَعَهُ مِنْ رِقَابِنَا سَتَعْرِفُ مَا هُوَ الْخِذْلَانُ حَقًّا", "segs": [{"ar": "وَأَنْتَ لَمْ تَرَ الْخِذْلَانَ بَعْدُ", "uz": "Sen hali xor bo'lishni ko'rmagansan"}, {"ar": "غَدًا عِنْدَمَا يَتَمَكَّنُ الْمَأْمُونُ وَمَنْ مَعَهُ مِنْ رِقَابِنَا", "uz": "ertaga al-Ma'mun va uning odamlari bo'ynimizga hukmron bo'lganida"}, {"ar": "سَتَعْرِفُ مَا هُوَ الْخِذْلَانُ حَقًّا", "uz": "haqiqiy xor bo'lish nima ekanini bilib olasan"}], "full_uz": "Sen hali xor bo'lishni ko'rmagansan — ertaga al-Ma'mun va uning odamlari bo'ynimizga hukmron bo'lganida, haqiqiy xor bo'lish nima ekanini bilib olasan.", "note": null},
  {"num": 62, "time": "00:04:46,540 --> 00:04:57,879", "arabic": "أَيُّهَا الْإِخْوَةُ، يَجِبُ أَنْ نُحَرِّضَ النَّاسَ فِي بَغْدَادَ عَلَى هَذَا الظَّالِمِ، يَجِبُ تَأْلِيبُهُمْ عَلَى الْأَمِينِ حَتَّى نُعَجِّلَ بِالْخَلَاصِ مِنْهُ", "segs": null, "full_uz": "Ey birodarlar, biz Bag'dod xalqini bu zolimga qarshi qo'zg'atishimiz kerak — undan tezroq qutulish uchun ularni al-Aminga qarshi qayrashimiz kerak.", "note": null},
  {"num": 64, "time": "00:04:57,879 --> 00:05:05,780", "arabic": "وَلَكِنْ كَيْفَ؟ وَهُوَ يَشْتَرِي الْمُؤَيِّدِينَ بِالنُّقُودِ وَيَصْرِفُ أَمْوَالًا طَائِلَةً لِتَجْنِيدِ النَّاسِ كَيْ تُقَاتِلَ عَنْهُ أَخَاهُ الْمَأْمُونَ", "segs": null, "full_uz": "Ammo qanday? U pul bilan tarafdorlar sotib olib, ukasi al-Ma'munga qarshi jang qilishlari uchun odamlarni jalb qilishga katta pul sarflayapti.", "note": null},
  {"num": 65, "time": "00:05:05,780 --> 00:05:12,879", "arabic": "أَلَيْسَتْ تِلْكَ أَمْوَالَ الْمُسْلِمِينَ يُبَعْثِرُهَا عَدُوُّ اللَّهِ ذَاكَ؟ يَقْتُلُ الْمُسْلِمِينَ بِأَمْوَالِ الْمُسْلِمِينَ", "segs": null, "full_uz": "Bu — o'sha Alloh dushmani sochib yotgan musulmonlar mollari emasmi? Musulmonlarni musulmonlarning moli bilan o'ldiryapti.", "note": null},
  {"num": 67, "time": "00:05:12,879 --> 00:05:20,120", "arabic": "إِنَّ كُلَّ سِلَاحٍ بِيَدِ الْجُنْدِ هُوَ مِنْ مَالِ الْمُسْلِمِينَ، فَكَيْفَ يَقْتُلُ الْمُسْلِمِينَ بِأَمْوَالِهِمْ؟", "segs": null, "full_uz": "Askarlar qo'lidagi har bir qurol musulmonlar molidan — u musulmonlarni ularning o'z moli bilan qanday o'ldirishi mumkin?", "note": null},
  {"num": 69, "time": "00:05:20,120 --> 00:05:25,219", "arabic": "هَذَا الْكَلَامُ يَجِبُ أَنْ يَصِلَ إِلَى النَّاسِ، أَيُّهَا الْإِخْوَةُ", "segs": null, "full_uz": "Bu gap odamlarga yetib borishi kerak, ey birodarlar.", "note": null},
  {"num": 71, "time": "00:05:25,219 --> 00:05:32,120", "arabic": "يَجِبُ أَنْ يَسْقُطَ مِنْ قُلُوبِ النَّاسِ قَبْلَ أَنْ يَسْقُطَ بِسُيُوفِ أَهْلِ خُرَاسَانَ، أَفَهِمْتُمْ؟ نَعَمْ", "segs": null, "full_uz": "U xurosonliklarning qilichlari bilan yiqilishidan oldin, odamlar qalbidan yiqilishi kerak. Tushundinglarmi? Ha.", "note": null},
  {"num": 75, "time": "00:05:32,120 --> 00:05:44,240", "arabic": "أَعْلَمُ أَنَّ أَمِيرَ الْمُؤْمِنِينَ لَدَيْهِ مَا يَشْغَلُهُ وَلَكِنْ رَأَيْتُ مِنْ وَاجِبِي أَنْ أَسْتَأْذِنَكَ قَبْلَ أَنْ أَخْرُجَ إِلَى مَكَّةَ الْمُكَرَّمَةِ", "segs": null, "full_uz": "Bilaman, Amir al-Mo'mininning bandligi bor, ammo Makka Mukarramaga chiqishdan oldin sizdan ijozat so'rashni o'zimga burch deb bildim.", "note": null},
  {"num": 77, "time": "00:05:44,240 --> 00:05:51,580", "arabic": "لَوْ أَمْتَعْتَنَا بِبَقَائِكَ يَا أَبَا عَبْدِ اللَّهِ، فَوَاللَّهِ رُؤْيَتُكَ تَشْرَحُ الصَّدْرَ", "segs": null, "full_uz": "Qolishingiz bilan bizni bahramand qilsangiz edi, Abu Abdulloh — Alloh haqi, sizni ko'rish ko'ngilni yozadi.", "note": null},
  {"num": 79, "time": "00:05:51,580 --> 00:05:58,480", "arabic": "رَغْمَ كَثْرَةِ الْهُمُومِ وَالْمُوَاجَهَةِ، لَا أَشْغَلَ اللَّهُ بَالَكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "G'am-tashvish va murosalarning ko'pligiga qaramay. Alloh sizning ko'nglingizni band qilmasin, Amir al-Mo'minin.", "note": null},
  {"num": 81, "time": "00:05:59,259 --> 00:06:04,840", "arabic": "إِنَّ لِلْأُمُورِ أَوَاخِرَ كَمَا أَنَّ لَهَا أَوَائِلَ", "segs": null, "full_uz": "Har bir ishning boshlanishi bo'lgani kabi, oxiri ham bor.", "note": "Bu hikmatona ibora — barcha ishlarning boshlanishi va yakuni borligini bildiradi."},
  {"num": 82, "time": "00:06:04,839 --> 00:06:13,839", "arabic": "وَإِنْ أَذِنْتَ لِي قُلْتُ شَيْئًا يَجْدُرُ بِمِثْلِي أَنْ يَقُولَهُ فِي سَاعَةٍ مِثْلِ هَذِهِ", "segs": null, "full_uz": "Agar ijozat bersangiz, menga o'xshagan kishiga shu kabi bir soatda aytish loyiq bo'lgan bir narsani aytaman.", "note": null},
  {"num": 83, "time": "00:06:13,839 --> 00:06:20,459", "arabic": "قُلْ يَا أَبَا عَبْدِ اللَّهِ، إِنِّي فِي شَغَفٍ لِسَمَاعِ كَلَامِكَ", "segs": null, "full_uz": "Ayting, Abu Abdulloh — gapingizni eshitishga ishtiyoqmandman.", "note": null},
  {"num": 85, "time": "00:06:20,459 --> 00:06:30,139", "arabic": "حَقْنُ دَمِ الْمُسْلِمِينَ أَوْلَى مِنْ سَفْكِهِ يَا أَمِيرَ الْمُؤْمِنِينَ، وَفِي الْحِوَارِ مَنْدُوحَةٌ بَيْنَ النَّاسِ", "segs": null, "full_uz": "Musulmonlar qonini to'kishdan ko'ra, uni saqlash afzalroqdir, Amir al-Mo'minin — muzokarada odamlar o'rtasida keng imkoniyat bor.", "note": null},
  {"num": 87, "time": "00:06:30,139 --> 00:06:41,140", "arabic": "فَكَيْفَ بِهِ بَيْنَ الْإِخْوَةِ مِنَ الْمُؤْمِنِينَ؟ أَمَّا بَعْدُ فَأَنْتَ أَمِيرُ الْمُؤْمِنِينَ وَنَجْلُ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Mo'min birodarlar o'rtasida esa qanday bo'lmasin? Ammo ba'du: siz Amir al-Mo'minin va Horun ar-Rashidning — Alloh unga rahmat qilsin — o'g'lisiz.", "note": null},
  {"num": 89, "time": "00:06:41,140 --> 00:06:53,220", "arabic": "وَخَصْمُكَ كَمَا تَرَاهُ الْأَمِيرُ الْمَأْمُونُ، فَهَلْ غَلَبَتْ يَا مَوْلَايَ حُرْمَةُ الدَّمِ وَصِلَةُ الرَّحِمِ عَلَى قِعَةِ السُّيُوفِ؟", "segs": [{"ar": "وَخَصْمُكَ كَمَا تَرَاهُ الْأَمِيرُ الْمَأْمُونُ", "uz": "Siz raqib deb bilgan kishi esa Amir al-Ma'mun"}, {"ar": "فَهَلْ غَلَبَتْ يَا مَوْلَايَ حُرْمَةُ الدَّمِ وَصِلَةُ الرَّحِمِ عَلَى قِعَةِ السُّيُوفِ؟", "uz": "qonning hurmati va qarindoshlik rishtasi qilichlar shovqinidan ustun keldimi, xo'jayinim?"}], "full_uz": "Siz raqib deb bilgan kishi esa Amir al-Ma'mun — qonning hurmati va qarindoshlik rishtasi qilichlar shovqinidan ustun keldimi, xo'jayinim?", "note": null},
  {"num": 91, "time": "00:06:59,220 --> 00:07:05,720", "arabic": "لَقَدْ سَبَقَ السَّيْفُ الْعَذَلَ يَا أَبَا عَبْدِ اللَّهِ، مَا دَامَ فِي الْقَلْبِ نِيَّةٌ", "segs": null, "full_uz": "Qilich koyishdan oldin ketdi, Abu Abdulloh. Qalbda niyat bo'lar ekan.", "note": "«سَبَقَ السَّيْفُ الْعَذَلَ» — mashhur arab maqoli, ish allaqachon qilinganidan keyin koyish foydasiz ekanini bildiradi."},
  {"num": 93, "time": "00:07:05,720 --> 00:07:11,420", "arabic": "وَفِي الْعَقْلِ رَأْيٌ وَفِي النَّفْسِ عَزْمٌ وَفِي الْوَقْتِ مُتَّسَعٌ", "segs": [{"ar": "وَفِي الْعَقْلِ رَأْيٌ", "uz": "Aqlda fikr bor ekan"}, {"ar": "وَفِي النَّفْسِ عَزْمٌ", "uz": "nafsda qat'iyat bor ekan"}, {"ar": "وَفِي الْوَقْتِ مُتَّسَعٌ", "uz": "vaqtda keng imkon bor ekan"}], "full_uz": "Aqlda fikr, nafsda qat'iyat va vaqtda keng imkon bor ekan.", "note": null},
  {"num": 95, "time": "00:07:11,420 --> 00:07:17,280", "arabic": "فَكُلُّ شَيْءٍ يُمْكِنُ تَدَارُكُهُ يَا أَمِيرَ الْمُؤْمِنِينَ، إِذَا انْطَلَقَ السَّهْمُ", "segs": null, "full_uz": "Har bir narsani tuzatib bo'ladi, Amir al-Mo'minin. Agar o'q otilib ketsa.", "note": null},
  {"num": 97, "time": "00:07:17,280 --> 00:07:26,680", "arabic": "فَلَا رَدَّ لَهُ يَا ابْنَ إِدْرِيسَ، وَلَكِنَّ الْحَرْبَ خَرَجَتْ مِنْ يَدِ أَخِي الْمَأْمُونِ", "segs": null, "full_uz": "Uni qaytarib bo'lmaydi, Ibn Idris. Ammo urush ukam al-Ma'munning qo'lidan chiqib ketdi.", "note": null},
  {"num": 99, "time": "00:07:26,680 --> 00:07:36,860", "arabic": "إِلَى يَدِ قَوْمٍ جُفَاةٍ غِلَاظٍ حَاقِدِينَ، لَنْ يَقْبَلُوا الصُّلْحَ حَتَّى لَوْ قَبِلَ أَخِي الْمَأْمُونُ", "segs": null, "full_uz": "Qo'pol, qattiqqo'l, hasadgo'y bir qavmning qo'liga. Ukam al-Ma'mun rozi bo'lsa ham, ular sulhga rozi bo'lishmaydi.", "note": null},
  {"num": 101, "time": "00:07:36,860 --> 00:07:50,000", "arabic": "هَذِهِ الْحَرْبُ أَصْبَحَتْ أَكْبَرَ مِنَّا جَمِيعًا، إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رُجُوعٌ", "segs": null, "full_uz": "Bu urush hammamizdan kattaroq bo'lib qoldi. Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": null},
  {"num": 103, "time": "00:08:01,680 --> 00:08:21,060", "arabic": "إِنَّ هَذِهِ الْحَرْبَ أَيُّهَا الْإِخْوَةُ وَبَالٌ عَلَى الْإِسْلَامِ", "segs": null, "full_uz": "Bu urush, ey birodarlar, Islom uchun ofatdir.", "note": null},
  {"num": 104, "time": "00:08:21,060 --> 00:08:29,639", "arabic": "لَمْ تَقُمْ لِإِعْلَاءِ كَلِمَةِ اللَّهِ بَلْ قَامَتْ مِنْ أَجْلِ مَطَامِعَ فِي الْحُكْمِ وَرَغْبَةٍ فَاسِدَةٍ فِي الِاسْتِئْثَارِ بِالسُّلْطَانِ", "segs": [{"ar": "لَمْ تَقُمْ لِإِعْلَاءِ كَلِمَةِ اللَّهِ", "uz": "U Alloh kalimasini yuksaltirish uchun boshlanmadi"}, {"ar": "بَلْ قَامَتْ مِنْ أَجْلِ مَطَامِعَ فِي الْحُكْمِ", "uz": "hokimiyatga tamagirlik uchun boshlandi"}, {"ar": "وَرَغْبَةٍ فَاسِدَةٍ فِي الِاسْتِئْثَارِ بِالسُّلْطَانِ", "uz": "va sultonlikni yolg'iz o'ziga olib qo'yishga bo'lgan buzuq istak uchun"}], "full_uz": "U Alloh kalimasini yuksaltirish uchun boshlanmadi — hokimiyatga tamagirlik va sultonlikni yolg'iz o'ziga olib qo'yishga bo'lgan buzuq istak uchun boshlandi.", "note": null},
  {"num": 107, "time": "00:08:29,639 --> 00:08:36,139", "arabic": "وَلَكِنَّ الْمَأْمُونَ هُوَ مَنْ بَدَأَ بِالشَّرِّ، هَيَّا يَقِنْ يَا أَخِي، إِنَّ مَنْ يُشَارِكُ فِي هَذِهِ الْحَرْبِ آثِمٌ", "segs": null, "full_uz": "Ammo yovuzlikni boshlagan al-Ma'mun-ku. Yur, ishonch bilan ayt, birodarim — bu urushga ishtirok etgan kishi gunohkordir.", "note": null},
  {"num": 110, "time": "00:08:36,139 --> 00:08:43,879", "arabic": "وَالْعَاقِلُ هُوَ مَنْ لَزِمَ دَارَهُ وَاعْتَزَلَ هَذَا الشَّرَّ وَالْخَوْضَ فِيهِ، أَتُحَرِّضُ النَّاسَ عَلَى وَلِيِّ الْأَمْرِ؟", "segs": [{"ar": "وَالْعَاقِلُ هُوَ مَنْ لَزِمَ دَارَهُ وَاعْتَزَلَ هَذَا الشَّرَّ وَالْخَوْضَ فِيهِ", "uz": "Aqlli kishi — bu uyida qolib, yovuzlikdan va unga aralashuvdan chetlashgan kishidir"}, {"ar": "أَتُحَرِّضُ النَّاسَ عَلَى وَلِيِّ الْأَمْرِ؟", "uz": "Odamlarni hokimga qarshi qo'zg'atyapsanmi?"}], "full_uz": "Aqlli kishi — bu uyida qolib, yovuzlikdan va unga aralashuvdan chetlashgan kishidir. Odamlarni hokimga qarshi qo'zg'atyapsanmi?", "note": null},
  {"num": 113, "time": "00:08:43,879 --> 00:08:49,519", "arabic": "إِنْ لَمْ تَخَفْ مِنَ اللَّهِ خَفِ مِنَ الْعَسَسِ، إِلَى مَتَى نَحْنِي رُءُوسَنَا أَمَامَ رِيَاحِ الظَّالِمِينَ", "segs": null, "full_uz": "Allohdan qo'rqmasang, jarchi(qorovul)dan qo'rq. Qachongacha zolimlar shamoli oldida boshimizni egib turamiz?", "note": "اَلْعَسَس — kechasi shahar bo'ylab yurib nazorat qiluvchi soqchilar."},
  {"num": 115, "time": "00:08:49,519 --> 00:08:54,039", "arabic": "وَنَرْكُضُ خَلْفَ الطُّغَاةِ، قُولُوا لِي إِلَى مَتَى", "segs": null, "full_uz": "Va tug'yon qiluvchilar ortidan yugurib yuramiz. Ayting menga, qachongacha?", "note": null},
  {"num": 117, "time": "00:08:54,039 --> 00:09:00,379", "arabic": "هَلْ يَتَحَمَّلُ الْأَمِينُ أَوْ أَخُوهُ وِزْرَ خَطَايَانَا أَمَامَ اللَّهِ؟ أَفِيقُوا أَيُّهَا الْمُسْلِمُونَ", "segs": null, "full_uz": "Al-Amin yoki uning ukasi Alloh oldida bizning gunohlarimiz yukini ko'taradimi? Uyg'oning, ey musulmonlar.", "note": null},
  {"num": 119, "time": "00:09:00,379 --> 00:09:07,639", "arabic": "أَفِيقُوا أَيُّهَا الْمُسْلِمُونَ، أَفِيقُوا أَيُّهَا النَّاسُ، أَفِيقُوا، أَفِيقُوا إِلَى مَتَى", "segs": null, "full_uz": "Uyg'oning, ey musulmonlar. Uyg'oning, ey odamlar. Uyg'oning. Uyg'oning — qachongacha?", "note": null},
  {"num": 123, "time": "00:09:07,639 --> 00:09:13,820", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh. Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 125, "time": "00:09:13,820 --> 00:09:23,899", "arabic": "اَللَّهُمَّ اغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَأَلِّفْ بَيْنَ قُلُوبِهِمْ", "segs": null, "full_uz": "Allohim, mo'min-mo'minalarni, musulmon-musulmalarni mag'firat qil va qalblari orasini ulfat qil.", "note": null},
  {"num": 128, "time": "00:09:23,899 --> 00:09:32,240", "arabic": "وَأَصْلِحْ ذَاتَ بَيْنِهِمْ وَاهْدِهِمْ سُبُلَ السَّلَامِ وَانْصُرْهُمْ عَلَى عَدُوِّكَ وَعَدُوِّهِمْ يَا رَحِيمَ الرَّاحِمِينَ", "segs": null, "full_uz": "Ularning orasini isloh qil, ularni salomatlik yo'llariga hidoyat qil va Sening hamda ularning dushmaniga qarshi ularga g'alaba ber, ey rahmlilarning eng rahmlisi.", "note": null},
  {"num": 131, "time": "00:09:32,240 --> 00:09:39,460", "arabic": "اَللَّهُمَّ أَبْرِمْ لِهَذِهِ الْأُمَّةِ أَمْرَ رُشْدٍ يَعِزُّ فِيهِ أَهْلُ طَاعَتِكَ", "segs": null, "full_uz": "Allohim, bu ummat uchun to'g'ri yo'l ishini mahkam qilgin — unda Senga itoat qiluvchilar aziz bo'lsin.", "note": null},
  {"num": 133, "time": "00:09:39,460 --> 00:09:44,879", "arabic": "وَيُذَلُّ فِيهِ أَهْلُ عَدَاوَتِكَ وَيُهْدَى فِيهِ أَهْلُ مَعْصِيَتِكَ", "segs": null, "full_uz": "Va unda Senga dushmanlik qiluvchilar xor bo'lsin, gunoh qiluvchilar hidoyat topsin.", "note": null},
  {"num": 135, "time": "00:09:44,879 --> 00:09:55,480", "arabic": "وَيُؤْمَرُ فِيهِ بِالْمَعْرُوفِ وَيُنْهَى فِيهِ عَنِ الْمُنْكَرِ، يَا رَبَّ الْعَالَمِينَ، يَا رَبِّ", "segs": null, "full_uz": "Va unda ma'rufga buyurilib, munkardan qaytarilsin, ey olamlar Robbi, ey Rabbim.", "note": null},
  {"num": 138, "time": "00:09:55,480 --> 00:10:20,820", "arabic": "لَمْ تَهْدَأِ الْأَصْوَاتُ مُنْذُ الْأَمْسِ، أَرَأَيْتَ إِلَى أَيْنَ أَوْصَلَنَا الْخِلَافُ بَيْنَ الْأَمِينِ وَالْمَأْمُونِ", "segs": null, "full_uz": "Ovozlar kechadan beri tinmadi. Ko'rdingizmi, al-Amin va al-Ma'mun o'rtasidagi ixtilof bizni qayerga olib keldi?", "note": null},
  {"num": 140, "time": "00:10:20,820 --> 00:10:25,939", "arabic": "حَتَّى طَالَتْ صَلَاةُ الْجَمَاعَةِ، اَللَّهُ الْمُسْتَعَانُ", "segs": null, "full_uz": "Hatto jamoat namozi ham cho'zilib ketdi. Alloh madadkordir.", "note": null},
  {"num": 142, "time": "00:10:25,939 --> 00:10:33,500", "arabic": "وَمَنْ يَجْرُؤُ الْآنَ عَلَى الْخُرُوجِ مِنْ بَيْتِهِ بَعْدَ أَنْ فَقَدَتْ بَغْدَادُ الْأَمْنَ وَالْأَمَانَ؟", "segs": null, "full_uz": "Bag'dod xavfsizlik va omonatni yo'qotgandan keyin, kim endi uydan chiqishga jur'at etadi?", "note": null},
  {"num": 144, "time": "00:10:33,500 --> 00:10:41,159", "arabic": "أَيُّ بَلَاءٍ حَلَّ بِكِ يَا بَغْدَادُ؟ أَجَلْ", "segs": null, "full_uz": "Qanday bir bало seni bosdi, Bag'dod? Ha.", "note": null},
  {"num": 146, "time": "00:10:41,159 --> 00:10:49,059", "arabic": "أَيُّ بَلَاءٍ حَلَّ بِكِ يَا بَغْدَادُ؟ يَبْدُو أَنَّ الشُّطَّارَ وَالْعَيَّارِينَ", "segs": null, "full_uz": "Qanday bало seni bosdi, Bag'dod? Ko'rinishidan, jinoyatchi va qaroqchilar.", "note": "اَلشُّطَّار وَالْعَيَّارُون — qadimgi islom shaharlarida tinchlikni buzuvchi jinoyatchi to'dalarga nisbatan ishlatilgan atama."},
  {"num": 148, "time": "00:10:49,059 --> 00:10:57,819", "arabic": "قَدْ وَجَدُوا الْفُرْصَةَ سَانِحَةً أَمَامَهُمْ فَلَمْ يَدَعُوا شَيْئًا إِلَّا وَأَخَذُوهُ", "segs": null, "full_uz": "Oldilarida qulay fursat topib, hech narsani qoldirmasdan olib ketishmoqda.", "note": null},
  {"num": 150, "time": "00:10:57,819 --> 00:11:09,839", "arabic": "وَلَمْ يَتْرُكُوا حَرَامًا إِلَّا وَانْتَهَكُوهُ، مَا كَانَ أَغْنَى الْمُسْلِمِينَ عَنْ ذَلِكَ لَوْ أَنَّ أَبْنَاءَ الرَّشِيدِ رَضُوا بِمَا أَنْزَلَ اللَّهُ عَلَى رَسُولِهِ", "segs": [{"ar": "وَلَمْ يَتْرُكُوا حَرَامًا إِلَّا وَانْتَهَكُوهُ", "uz": "Va hech bir haromni qoldirmasdan buzishmoqda"}, {"ar": "مَا كَانَ أَغْنَى الْمُسْلِمِينَ عَنْ ذَلِكَ لَوْ أَنَّ أَبْنَاءَ الرَّشِيدِ رَضُوا بِمَا أَنْزَلَ اللَّهُ عَلَى رَسُولِهِ", "uz": "ar-Rashidning o'g'illari Alloh o'z Rasuliga nozil qilgan narsaga rozi bo'lganida, musulmonlar bunga muhtoj bo'lmasdi"}], "full_uz": "Va hech bir haromni qoldirmasdan buzishmoqda — ar-Rashidning o'g'illari Alloh o'z Rasuliga nozil qilgan narsaga rozi bo'lganida, musulmonlar bunga muhtoj bo'lmasdi.", "note": null},
  {"num": 152, "time": "00:11:09,839 --> 00:11:16,379", "arabic": "وَغَلَّبُوا الْمَصْلَحَةَ الْعَامَّةَ عَلَى الْخَاصَّةِ، وَلَكِنْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Va umumiy manfaatni shaxsiy manfaatdan ustun qo'yganida. Ammo la havla va la quvvata illa billah.", "note": null},
  {"num": 154, "time": "00:11:16,379 --> 00:11:21,899", "arabic": "إِنَّ مَنْ يَدْفَعُ الثَّمَنَ الْآنَ قَوْمٌ لَا نَاقَةَ لَهُمْ وَلَا جَمَلَ فِي هَذِهِ الْحَرْبِ", "segs": null, "full_uz": "Hozir bahosini to'layotganlar — bu urushda hech qanday aloqasi bo'lmagan xalqdir.", "note": "لَا نَاقَةَ لَهُ وَلَا جَمَل — biror ishga aloqasi yo'q kishi haqidagi mashhur arab iborasi."},
  {"num": 155, "time": "00:11:21,899 --> 00:11:29,419", "arabic": "اَللَّهُمَّ احْقِنْ دِمَاءَ الْمُسْلِمِينَ وَكُفَّنَا شَرَّ الْفِتَنِ", "segs": null, "full_uz": "Allohim, musulmonlarning qonini saqla va bizni fitnalarning yovuzligidan asra.", "note": null},
  {"num": 157, "time": "00:11:29,419 --> 00:11:36,279", "arabic": "مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَاجْمَعْ كَلِمَتَهُمْ عَلَى سَوَاءٍ", "segs": null, "full_uz": "Ochig'idan ham, yashiringanidan ham. Va ularning so'zini bir yerga jam qil.", "note": null},
  {"num": 159, "time": "00:11:36,279 --> 00:11:46,059", "arabic": "وَاحْفَظْ لَنَا الْحُرُمَاتِ وَكُفَّ عَنَّا الْكُرُبَاتِ، اَللَّهُمَّ آمِينَ آمِينَ", "segs": null, "full_uz": "Va bizga muqaddasotlarni saqla, bizdan mashaqqatlarni to'sib qo'y. Omin, Allohim, omin.", "note": null},
  {"num": 163, "time": "00:11:51,899 --> 00:12:51,879", "arabic": "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "segs": null, "full_uz": "Allohga la'natlangan shaytondan sig'inaman. Rahmон va Rahim bo'lgan Alloh nomi bilan.", "note": null},
  {"num": 166, "time": "00:12:51,899 --> 00:12:59,899", "arabic": "وَالِدِي، وَالِدِي، أَيْنَ أَنْتَ يَا وَالِدِي؟ وَالِدِي، هَلْ رَأَيْتَ وَالِدِي؟", "segs": null, "full_uz": "Otam, otam, qayerdasan, otajon? Otam. Otamni ko'rdingizmi?", "note": null},
  {"num": 168, "time": "00:12:59,899 --> 00:13:47,899", "arabic": "وَالِدِي، وَالِدِي", "segs": null, "full_uz": "Otam, otam.", "note": null},
  {"num": 170, "time": "00:13:47,899 --> 00:13:52,059", "arabic": "إِنَّ أَهْلَ الْمَدِينَةِ يَتْرُكُونَ بُيُوتَهُمْ وَيَفِرُّونَ", "segs": null, "full_uz": "Shahar ahli uylarini tashlab qochmoqda.", "note": null},
  {"num": 171, "time": "00:13:52,059 --> 00:14:00,459", "arabic": "إِلَى أَيْنَ يَفِرُّونَ؟ إِنَّهُمْ خَائِفُونَ مِنْ جُنْدِ طَاهِرِ بْنِ الْحُسَيْنِ مِنْ دُخُولِ الْمَدِينَةِ وَاسْتِبَاحَتِهَا", "segs": null, "full_uz": "Qayerga qochishyapti? Ular Tohir ibn al-Husayn qo'shinlarining shaharga kirib, uni talon-tarоj qilishidan qo'rqishmoqda.", "note": null},
  {"num": 173, "time": "00:14:00,459 --> 00:14:14,019", "arabic": "فَلْيَذْهَبِ ابْنُ الْحُسَيْنِ إِلَى الْجَحِيمِ، أَيْنَ الْجُنْدُ؟ أَيْنَ الْقَادَةُ؟ أَيْنَ الْأُمَرَاءُ؟ أَيْنَ هُمْ؟", "segs": null, "full_uz": "Ibn al-Husayn do'zaxga borsin. Qo'shin qayerda? Sarkardalar qayerda? Amirlar qayerda? Ular qayerda?", "note": null},
  {"num": 175, "time": "00:14:14,019 --> 00:14:18,759", "arabic": "لَقَدْ فَرَّ أَكْثَرُ جُنْدِكَ إِلَى طَاهِرِ بْنِ الْحُسَيْنِ وَأَخَذَ مِنْهُ الْأَمَانَ", "segs": null, "full_uz": "Qo'shiningizning ko'pchiligi Tohir ibn al-Husaynga qochib, undan omonlik olishdi.", "note": null},
  {"num": 177, "time": "00:14:18,759 --> 00:14:24,319", "arabic": "وَهُمْ يُقَاتِلُونَ الْآنَ فِي صُفُوفِ جَيْشِهِ، سُحْقًا لَهُ وَلَهُمْ", "segs": null, "full_uz": "Va hozir uning qo'shini saflarida jang qilishmoqda. Ularga va unga la'nat bo'lsin.", "note": null},
  {"num": 179, "time": "00:14:24,319 --> 00:14:33,019", "arabic": "مِنْ أَيْنَ آتِي بِحَظٍّ كَحَظِّ طَاهِرِ بْنِ الْحُسَيْنِ؟", "segs": null, "full_uz": "Tohir ibn al-Husaynning omadi kabi omadni men qayerdan topaman?", "note": null},
  {"num": 180, "time": "00:14:34,539 --> 00:14:43,019", "arabic": "إِنَّ جُنْدِيًّا مِنْ جُنُودِي يَأْخُذُ نَفَقَةً أَضْعَافَ مَا يَأْخُذُ طَاهِرٌ مِنَ الْمَأْمُونِ وَهُمْ يَفِرُّونَ كَالْجِرْذَانِ", "segs": null, "full_uz": "Askarlarimdan biri Tohir al-Ma'mundan olgan xarajatidan necha barobar ko'p oladi-yu, ular kalamush kabi qochishmoqda.", "note": null},
  {"num": 183, "time": "00:14:44,019 --> 00:14:49,879", "arabic": "أَعُوذُ بِاللَّهِ مِنَ الْخِذْلَانِ، أَعُوذُ بِاللَّهِ مِنَ الْخِذْلَانِ", "segs": null, "full_uz": "Allohga xor bo'lishdan sig'inaman. Allohga xor bo'lishdan sig'inaman.", "note": null},
  {"num": 185, "time": "00:14:49,879 --> 00:14:52,899", "arabic": "وَمِنَ الذُّلِّ وَقَهْرِ الرِّجَالِ", "segs": null, "full_uz": "Va zillatdan hamda erkaklarning qahridan.", "note": null},
  {"num": 187, "time": "00:14:52,899 --> 00:15:00,019", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ، وَجَدْتَهُ؟", "segs": null, "full_uz": "Amir al-Mo'mininga salom. Uni topdingizmi?", "note": null},
  {"num": 189, "time": "00:15:00,019 --> 00:15:07,019", "arabic": "بَحَثْتُ عَنْهُ فِي كُلِّ مَكَانٍ وَلَمْ أَجِدْهُ، أَيْنَ ذَهَبَ؟", "segs": null, "full_uz": "Uni hamma yerdan qidirdim, topolmadim. Qayerga ketdi?", "note": null},
  {"num": 192, "time": "00:15:07,019 --> 00:15:13,779", "arabic": "أَيْنَ ذَهَبَ ابْنُ الرَّبِيعِ هَذَا؟ بَحَثْتُ عَنْهُ فِي كُلِّ مَكَانٍ وَلَكِنْ", "segs": null, "full_uz": "Bu Ibn ar-Rabi' qayerga ketdi? Uni hamma yerdan qidirdim, ammo...", "note": null},
  {"num": 195, "time": "00:15:13,779 --> 00:15:24,360", "arabic": "جِدُّوهُ لِي يَا مَسْرُورُ، فَتِّشْ عَنْهُ فِي كُلِّ مَكَانٍ", "segs": null, "full_uz": "Uni men uchun toping, Masrur — uni hamma yerdan qidiring.", "note": null},
  {"num": 197, "time": "00:15:24,360 --> 00:15:28,419", "arabic": "أُرِيدُهُ الْآنَ أَمَامِي", "segs": null, "full_uz": "Uni hozir oldimda ko'rmoqchiman.", "note": null},
  {"num": 199, "time": "00:15:28,419 --> 00:15:36,139", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ، وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Amir al-Mo'minin va uning hamrohlariga salom. Va alaykum assalom.", "note": null},
  {"num": 201, "time": "00:15:36,139 --> 00:15:47,600", "arabic": "وَزِيرُكَ الْفَضْلُ بْنُ الرَّبِيعِ يَا مَوْلَايَ، هَرَبَ، هَرَبَ", "segs": null, "full_uz": "Vaziringiz al-Fadl ibn ar-Rabi', xo'jayinim — qochib ketdi. Qochib ketdi.", "note": null},
  {"num": 204, "time": "00:15:47,600 --> 00:15:54,699", "arabic": "هَرَبَ بَعْدَ أَنْ زَيَّنَ لِي خَلْعَ الْمَأْمُونِ", "segs": null, "full_uz": "Al-Ma'munni taxtdan tushirishni menga chiroyli ko'rsatgandan keyin qochib ketdi.", "note": null},
  {"num": 205, "time": "00:15:54,699 --> 00:15:58,740", "arabic": "وَالْبَيْعَةَ لِابْنِيَ مُوسَى وَلِيًّا لِلْعَهْدِ", "segs": null, "full_uz": "Va o'g'lim Musoni valiahd qilib bay'at olishni ham.", "note": null},
  {"num": 206, "time": "00:16:07,539 --> 00:16:08,740", "arabic": "تَبًّا", "segs": null, "full_uz": "La'nat bo'lsin.", "note": null},
  {"num": 207, "time": "00:16:08,740 --> 00:17:54,220", "arabic": "كُلُّهُمْ أَرْوَغُ مِنْ ثَعْلَبٍ، مَا أَشْبَهَ اللَّيْلَةَ بِالْبَارِحَةِ", "segs": null, "full_uz": "Ularning hammasi tulkidan ham ayyorroq. Bu kecha o'tgan kechaga qanchalik o'xshaydi.", "note": "«مَا أَشْبَهَ اللَّيْلَةَ بِالْبَارِحَةِ» — mashhur arab maqoli, «hech narsa o'zgarmagan, xuddi o'sha voqea takrorlanmoqda» ma'nosida."},
  {"num": 214, "time": "00:18:22,220 --> 00:18:54,220", "arabic": "مَرْحَبًا", "segs": null, "full_uz": "Xush kelibsiz.", "note": null},
  {"num": 216, "time": "00:19:22,220 --> 00:19:26,380", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "La havla va la quvvata illa billah.", "note": null},
  {"num": 217, "time": "00:19:26,380 --> 00:19:31,000", "arabic": "اَللَّهُمَّ اكْشِفْ هَذِهِ الْغُمَّةَ وَجَنِّبِ الْمَسْجِدَيْنِ الْفِتَنَ", "segs": null, "full_uz": "Allohim, bu qayg'uni ochgin va ikki masjidni fitnalardan asrgin.", "note": "اَلْمَسْجِدَانِ — Makka va Madinadagi ikki muqaddas masjidga ishora."},
  {"num": 218, "time": "00:19:31,000 --> 00:19:46,299", "arabic": "جِئْتُ أَطْمَئِنُّ عَلَيْكُمْ، هَلِ الْجَمِيعُ بِخَيْرٍ؟", "segs": null, "full_uz": "Sizlardan xabar olgani keldim. Hammangiz sog'-omonmisiz?", "note": null},
  {"num": 219, "time": "00:19:46,299 --> 00:19:48,799", "arabic": "حَتَّى الْآنَ بِخَيْرٍ، نَتَهَيَّأُ لِنَخْرُجَ مِنْ هُنَا", "segs": null, "full_uz": "Hozircha yaxshimiz — bu yerdan chiqishga tayyorlanyapmiz.", "note": null},
  {"num": 220, "time": "00:19:48,799 --> 00:19:53,259", "arabic": "نَذْهَبُ وَأُحْضِرُ أُمَّكِ لِنُغَادِرَ سَوِيًّا، أَيْنَ سَنَذْهَبُ؟ أَنَا فَرٌّ كَمَا فَرَّ النَّاسُ", "segs": [{"ar": "نَذْهَبُ وَأُحْضِرُ أُمَّكِ لِنُغَادِرَ سَوِيًّا", "uz": "Ketamiz, onangni ham olib, birga chiqib ketamiz"}, {"ar": "أَيْنَ سَنَذْهَبُ؟ أَنَا فَرٌّ كَمَا فَرَّ النَّاسُ", "uz": "Qayerga boramiz? Odamlar qochgandek men ham qochyapman"}], "full_uz": "Ketamiz, onangni ham olib, birga chiqib ketamiz. Qayerga boramiz? Odamlar qochgandek men ham qochyapman.", "note": null},
  {"num": 222, "time": "00:19:53,259 --> 00:19:57,840", "arabic": "نَخْرُجُ مِنْ هَذِهِ الْفَوْضَى وَهَذِهِ الدِّمَاءِ، أَنَا فَرٌّ مِنْ قَدَرِ اللَّهِ إِلَى قَدَرِ اللَّهِ", "segs": null, "full_uz": "Bu tartibsizlik va qonlardan chiqib ketamiz. Men Allohning qazosidan Allohning qazosiga qochyapman.", "note": null},
  {"num": 224, "time": "00:19:57,840 --> 00:20:01,960", "arabic": "خُرُوجُنَا وَبَقَاؤُنَا سَوَاءٌ، لَنْ نُغَادِرَ بَغْدَادَ مَهْمَا حَدَثَ", "segs": null, "full_uz": "Chiqishimiz ham, qolishimiz ham bir xil. Nima bo'lsa ham, Bag'dodni tark etmaymiz.", "note": null},
  {"num": 226, "time": "00:20:01,960 --> 00:20:06,360", "arabic": "وَحَسْبُنَا اللَّهُ عَلَى بَغْدَادَ، وَحَسْبُنَا اللَّهُ عَلَى بَغْدَادَ", "segs": null, "full_uz": "Bag'dod uchun bizga Alloh yetarli, Bag'dod uchun bizga Alloh yetarli.", "note": null},
  {"num": 228, "time": "00:20:06,360 --> 00:20:50,700", "arabic": "بِاسْمِ اللَّهِ وَنِعْمَ الْوَطَنِ", "segs": null, "full_uz": "Alloh nomi bilan — vatan naqadar go'zal ne'mat.", "note": null},
  {"num": 230, "time": "00:20:50,700 --> 00:20:52,340", "arabic": "أَلَمْ يَكُنْ أَفْضَلَ؟", "segs": null, "full_uz": "Yaxshiroq bo'lmasmidi?", "note": null},
  {"num": 231, "time": "00:20:52,340 --> 00:21:00,840", "arabic": "اَلْمَوْتُ صَارَ فِي كُلِّ مَكَانٍ يَا فَوْزُ، وَمَا يُوجِعُ قَلْبِي أَنَّ الْقَاتِلَ مُسْلِمٌ وَالْمَقْتُولَ مُسْلِمٌ", "segs": [{"ar": "اَلْمَوْتُ صَارَ فِي كُلِّ مَكَانٍ يَا فَوْزُ", "uz": "O'lim hamma yerda bo'lib qoldi, Favz"}, {"ar": "وَمَا يُوجِعُ قَلْبِي أَنَّ الْقَاتِلَ مُسْلِمٌ وَالْمَقْتُولَ مُسْلِمٌ", "uz": "yuragimni og'ritadigani, qotil ham musulmon, o'ldirilgan ham musulmon"}], "full_uz": "O'lim hamma yerda bo'lib qoldi, Favz — yuragimni og'ritadigani, qotil ham musulmon, o'ldirilgan ham musulmon.", "note": null},
  {"num": 235, "time": "00:21:00,840 --> 00:21:50,680", "arabic": "كَثِيرٌ مِنَ الْأَبْرِيَاءِ يُقْتَلُونَ دُونَ أَيِّ ذَنْبٍ، اَللَّهُ الْمُسْتَعَانُ", "segs": null, "full_uz": "Ko'p begunohlar hech qanday aybsiz o'ldirilmoqda. Alloh madadkordir.", "note": null},
  {"num": 239, "time": "00:21:50,700 --> 00:22:05,400", "arabic": "لَنْ يَكُفُّوا حَتَّى يَجْعَلُوهَا رُكَامًا فَوْقَ رُءُوسِنَا", "segs": null, "full_uz": "Uni boshimiz ustidagi vайronaga aylantirmaguncha to'xtashmaydi.", "note": null},
  {"num": 240, "time": "00:22:05,400 --> 00:22:08,059", "arabic": "لَيْتَنَا خَرَجْنَا بِالْأَمْسِ", "segs": null, "full_uz": "Koshki kechayoq chiqib ketganimizda.", "note": null},
  {"num": 241, "time": "00:22:12,940 --> 00:22:15,100", "arabic": "لَمْ تَكُنِ الدُّرُوبُ آمِنَةً", "segs": null, "full_uz": "Yo'llar xavfsiz emas edi.", "note": null},
  {"num": 242, "time": "00:22:15,100 --> 00:22:20,660", "arabic": "إِنَّهُمْ يُطَوِّقُونَ بَغْدَادَ مِنْ كُلِّ طَرَفٍ وَيُغْلِقُونَ جَمِيعَ مَنَافِذِهَا", "segs": null, "full_uz": "Ular Bag'dodni har tarafdan qamal qilib, barcha chiqish yo'llarini yopmoqda.", "note": null},
  {"num": 244, "time": "00:22:20,660 --> 00:22:26,519", "arabic": "وَهَلْ سَتَنْتَظِرُ حَتَّى يُلْقُوا الْقَبْضَ عَلَيْكَ فِي قَصْرِكَ أَوْ يَجْعَلُونَهُ رُكَامًا فَوْقَ رُءُوسِنَا؟", "segs": null, "full_uz": "Saroyingda sени qo'lga olishlarini yoki uni boshimiz ustiga vайronaga aylantirishlarini kutasanmi?", "note": null},
  {"num": 246, "time": "00:22:26,519 --> 00:22:32,300", "arabic": "وَمَا عَسَايَ أَنْ أَفْعَلَ؟ إِنَّنِي هُنَا لَا حَوْلَ لِي وَلَا قُوَّةَ", "segs": null, "full_uz": "Nima qila olaman? Bu yerda mening ne hol, ne quvvatim yo'q.", "note": null},
  {"num": 248, "time": "00:22:32,300 --> 00:22:38,200", "arabic": "لَمْ يَبْقَ مَعِي إِلَّا ثُلَّةٌ مِنَ الرِّجَالِ يَتَحَسَّسُونَ أَعْنَاقَهُمْ، وَاللَّهِ", "segs": null, "full_uz": "Yonimda faqat bo'yinlarini paypaslab yurgan bir hovuch odam qoldi. Alloh haqi.", "note": null},
  {"num": 251, "time": "00:22:38,200 --> 00:22:45,019", "arabic": "سَيَلْحَقُونَ بِجُنْدِ الْمَأْمُونِ عَاجِلًا أَمْ آجِلًا، إِنْ أَلْقَى جُنُودُ الطَّاهِرِ بْنِ الْحُسَيْنِ الْقَبْضَ عَلَيْكَ", "segs": null, "full_uz": "Erta-kech al-Ma'mun qo'shiniga qo'shilishadi. Agar Tohir ibn al-Husayn askarlari seni qo'lga olsa.", "note": null},
  {"num": 253, "time": "00:22:45,019 --> 00:22:52,620", "arabic": "لَا يَمْنَعُهُمْ شَيْءٌ مِنْ قَتْلِكَ، أَرَى أَنْ تَخْرُجَ تَحْتَ جُنْحِ اللَّيْلِ إِلَى الْجِهَةِ الَّتِي يُسَيْطِرُ عَلَيْهَا هَرْثَمَةُ بْنُ أَعْيَنَ", "segs": [{"ar": "لَا يَمْنَعُهُمْ شَيْءٌ مِنْ قَتْلِكَ", "uz": "Seni o'ldirishdan hech narsa ularni to'sib qololmaydi"}, {"ar": "أَرَى أَنْ تَخْرُجَ تَحْتَ جُنْحِ اللَّيْلِ", "uz": "Fikrimcha, tun qorong'usida chiqib ketishing kerak"}, {"ar": "إِلَى الْجِهَةِ الَّتِي يُسَيْطِرُ عَلَيْهَا هَرْثَمَةُ بْنُ أَعْيَنَ", "uz": "Harsama ibn A'yan nazorat qiladigan tarafga"}], "full_uz": "Seni o'ldirishdan hech narsa ularni to'sib qololmaydi. Fikrimcha, tun qorong'usida Harsama ibn A'yan nazorat qiladigan tarafga chiqib ketishing kerak.", "note": null},
  {"num": 255, "time": "00:22:52,620 --> 00:22:58,980", "arabic": "هَرْثَمَةُ؟ هَرْثَمَةُ بْنُ أَعْيَنَ؟ إِنَّهُ أَشَدُّ وَطْأَةً مِنَ الطَّاهِرِ بْنِ الْحُسَيْنِ", "segs": null, "full_uz": "Harsama? Harsama ibn A'yanmi? U Tohir ibn al-Husayndan ham qattiqqo'lroq.", "note": null},
  {"num": 258, "time": "00:22:58,980 --> 00:23:06,640", "arabic": "فَكِلَاهُمَا يَتَسَابَقُ لِإِظْهَارِ وَلَائِهِ لِلْمَأْمُونِ، بَلْ هَرْثَمَةُ رَجُلٌ حَكِيمٌ وَهُوَ لَنْ يُؤْذِيَكَ وَأَنْتَ أَخُو الْمَأْمُونِ", "segs": null, "full_uz": "Ikkalasi ham al-Ma'munga bo'lgan sodiqligini ko'rsatishga poyga qilishadi. Yo'q, Harsama hakim odam va u al-Ma'munning akasi bo'lganing uchun senga zarar yetkazmaydi.", "note": null},
  {"num": 260, "time": "00:23:06,640 --> 00:23:12,040", "arabic": "ثُمَّ إِنَّهُ كَانَ مِنْ أَشْيَاخِكَ وَأَتْبَاعِكَ، كَمَا أَنَّهُ سَيَحْفَظُ لِأَبِيكَ إِكْرَامَهُ لَهُ", "segs": null, "full_uz": "Yana, u sening shayxlaring va izdoshlaringdan biri edi — otangning unga ko'rsatgan hurmatini ham eslab qolar.", "note": null},
  {"num": 262, "time": "00:23:12,040 --> 00:23:21,940", "arabic": "كَمَا سَيَحْفَظُ لِأَخِيكَ ذَلِكَ، أَوْصَلَ بِيَ الْخِذْلَانُ إِلَى التَّشَفُّعِ بِعَدُوِّي إِلَى عَدُوِّي", "segs": null, "full_uz": "Akangga bo'lgan hurmatini ham saqlaydi. Xor bo'lish meni dushmanimga qarshi dushmanimdan shafoat so'rashga olib keldi.", "note": null},
  {"num": 264, "time": "00:23:21,940 --> 00:23:28,960", "arabic": "بَائِسَةٌ الدُّنْيَا وَبَائِسٌ مَنْ يَحْرِصُ عَلَيْهَا", "segs": null, "full_uz": "Dunyo baxtsizdir, unga tirishuvchi ham baxtsizdir.", "note": null},
  {"num": 266, "time": "00:23:35,860 --> 00:23:40,759", "arabic": "اَلْمَأْمُونُ لَيْسَ عَدُوَّكَ يَا مُحَمَّدُ، إِنَّهُ أَخُوكَ", "segs": null, "full_uz": "Al-Ma'mun sening dushmaning emas, Muhammad — u sening akangdir.", "note": null},
  {"num": 268, "time": "00:23:40,759 --> 00:23:48,900", "arabic": "وَلَوْلَا الْوُشَاةُ وَالْمُغَرِّدُونَ الَّذِينَ فَرَّقُوا بَيْنَكُمْ لَمَا وَصَلَتِ الْحَالُ إِلَى مَا وَصَلَتْ إِلَيْهِ الْآنَ", "segs": null, "full_uz": "Agar oralaringizni buzgan g'iybatchi va fitnachilar bo'lmaganida, ish hozirgi holatga yetib bormasdi.", "note": null},
  {"num": 270, "time": "00:23:48,900 --> 00:24:34,539", "arabic": "يَبْدُو أَنَّنِي تَمَادَيْتُ فِي خَطَئِي إِلَى الْحَدِّ الَّذِي أَسْتَحِقُّ عَلَيْهِ مَا يَجْرِي", "segs": null, "full_uz": "Ko'rinishidan, xatoimda shu darajaga borib yetganman — sodir bo'layotgan narsaga loyiqman.", "note": null},
  {"num": 273, "time": "00:24:40,759 --> 00:24:47,079", "arabic": "مُوسَى وَعَبْدُ اللَّهِ أَمَانَةٌ لَدَيْكَ يَا أَبَا هَاشِمٍ، أَحْمَدُ اللَّهَ مِنْكَ", "segs": null, "full_uz": "Muso va Abdulloh senga omonat, Abu Hoshim. Alloh haqi so'rayman sendan.", "note": null},
  {"num": 275, "time": "00:24:47,079 --> 00:24:50,700", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatullohi va barakatuh.", "note": null},
  {"num": 277, "time": "00:24:50,700 --> 00:25:40,740", "arabic": "نَحْنُ جَاهِزُونَ لِلْخُرُوجِ إِلَى هَرْثَمَةَ يَا أَبَا مُوسَى، إِنَّهُ يَنْتَظِرُكَ عَلَى شَاطِئِ دِجْلَةَ", "segs": null, "full_uz": "Biz Harsamaga chiqishga tayyormiz, Abu Muso — u sizni Dajla qirg'og'ida kutmoqda.", "note": null},
  {"num": 280, "time": "00:25:40,759 --> 00:27:10,740", "arabic": "بَغْدَادُ", "segs": null, "full_uz": "Bag'dod.", "note": null},
  {"num": 284, "time": "00:27:10,759 --> 00:27:25,140", "arabic": "مَنْ ذَا أَصَابَكِ يَا بَغْدَادُ بِالْعَيْنِ؟ أَلَمْ تَكُونِي زَمَانًا قُرَّةَ الْعَيْنِ؟", "segs": [{"ar": "مَنْ ذَا أَصَابَكِ يَا بَغْدَادُ بِالْعَيْنِ؟", "uz": "Kim seni ko'z tegdirdi, ey Bag'dod?"}, {"ar": "أَلَمْ تَكُونِي زَمَانًا قُرَّةَ الْعَيْنِ؟", "uz": "Ilgari sen ko'zning nuri emasmiding?"}], "full_uz": "Kim seni ko'z tegdirdi, ey Bag'dod? Ilgari sen ko'zning nuri emasmiding?", "note": "قُرَّةُ الْعَيْن — «ko'zning quvonchi», suyukli, aziz narsa haqida ishlatiladigan ibora."},
  {"num": 286, "time": "00:27:40,759 --> 00:29:37,819", "arabic": "مَنْ ذَا أَصَابَكِ يَا بَغْدَادُ بِالْعَيْنِ؟ أَلَمْ تَكُونِي يَوْمًا قُرَّةَ الْعَيْنِ؟", "segs": null, "full_uz": "Kim seni ko'z tegdirdi, ey Bag'dod? Bir kun sen ko'zning nuri emasmiding?", "note": null},
  {"num": 293, "time": "00:29:37,839 --> 00:29:44,899", "arabic": "لِكَيْ نَعْلَمَ قِينًا مِنْ ذَلِكَ، اَلْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ", "segs": null, "full_uz": "Bundan aniq bilishimiz uchun — aka otasining o'g'lini o'ldirmaydi.", "note": null},
  {"num": 295, "time": "00:29:44,899 --> 00:29:54,839", "arabic": "اَلْمَأْمُونُ أَعْقَلُ مِنْ ذَلِكَ بِكَثِيرٍ، اَلدِّينُ وَالدَّمُ يَأْبَيَانِ ذَلِكَ", "segs": null, "full_uz": "Al-Ma'mun bundan ancha aqllidir — din va qon buni rad etadi.", "note": null},
  {"num": 297, "time": "00:29:55,559 --> 00:30:00,980", "arabic": "اَلْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ", "segs": null, "full_uz": "Aka otasining o'g'lini o'ldirmaydi.", "note": null},
  {"num": 298, "time": "00:30:07,839 --> 00:30:21,000", "arabic": "كَمْ جَرَيَا فِي هَذَا الْمَكَانِ عِنْدَمَا كَانُوا صِغَارًا، كَمْ تَسَابَقَا وَتَنَاقَشَا", "segs": [{"ar": "كَمْ جَرَيَا فِي هَذَا الْمَكَانِ عِنْدَمَا كَانُوا صِغَارًا", "uz": "Kichikliklarida bu joyda qancha yugurishgan"}, {"ar": "كَمْ تَسَابَقَا وَتَنَاقَشَا", "uz": "qancha musobaqalashib, bahslashishgan"}], "full_uz": "Kichikliklarida bu joyda qancha yugurishgan, qancha musobaqalashib, bahslashishgan.", "note": null},
  {"num": 300, "time": "00:30:21,000 --> 00:30:28,279", "arabic": "وَرُبَّمَا تَشَاجَرَا، لَكِنَّهُمَا لَمْ يَتَقَاتَلَا", "segs": null, "full_uz": "Va balki janjallashishgan ham, lekin bir-birlariga qarshi urushmasdilar.", "note": null},
  {"num": 302, "time": "00:30:28,279 --> 00:30:33,119", "arabic": "لَا، لَمْ يَتَقَاتَلَا", "segs": null, "full_uz": "Yo'q, urushmasdilar.", "note": null},
  {"num": 304, "time": "00:30:33,119 --> 00:30:37,739", "arabic": "اَلْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ", "segs": null, "full_uz": "Aka otasining o'g'lini o'ldirmaydi.", "note": null},
  {"num": 305, "time": "00:30:37,739 --> 00:30:53,119", "arabic": "غَدًا سَيَلْتَقِي الْأَمِينُ أَمِيرُ الْمُؤْمِنِينَ لِوَلِيِّ عَهْدِهِ الْمَأْمُونِ", "segs": null, "full_uz": "Ertaga Amir al-Mo'minin al-Amin o'z valiahdi al-Ma'mun bilan uchrashadi.", "note": null},
  {"num": 307, "time": "00:30:53,119 --> 00:30:58,819", "arabic": "وَسَيَنْتَهِي كُلُّ شَيْءٍ، نَعَمْ", "segs": null, "full_uz": "Va hammasi tugaydi. Ha.", "note": null},
  {"num": 310, "time": "00:30:58,819 --> 00:31:07,820", "arabic": "أَنَا عَلَى يَقِينٍ مِنْ ذَلِكَ، فَالْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ", "segs": null, "full_uz": "Men bunga ishonchim komil — aka otasining o'g'lini o'ldirmaydi.", "note": null},
  {"num": 312, "time": "00:31:07,820 --> 00:31:13,100", "arabic": "فَالْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ", "segs": null, "full_uz": "Aka otasining o'g'lini o'ldirmaydi.", "note": null},
  {"num": 313, "time": "00:31:13,100 --> 00:31:19,040", "arabic": "أَيُّهَا الْإِخْوَةُ، هَذِهِ نِهَايَةُ الطَّاغِيَةِ، اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Ey birodarlar, bu tug'yonchining oxiri. Alhamdulillah.", "note": null},
  {"num": 316, "time": "00:31:19,040 --> 00:31:27,060", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي أَرَاحَنَا مِنْ فِرْعَوْنَ آخَرَ، نَرْجُو أَنْ يُتِمَّ اللَّهُ الْأُمُورَ عَلَى خَيْرٍ", "segs": null, "full_uz": "Bizni yana bir Fir'avndan qutqargan Allohga hamd bo'lsin — Alloh ishlarni yaxshilikka yetkazishini umid qilamiz.", "note": null},
  {"num": 318, "time": "00:31:27,060 --> 00:31:33,240", "arabic": "وَتَجْرِي كَمَا نَظُنُّ وَنَحْسُبُ، لَمْ يَبْقَ لَهُ شَيْءٌ فِي بَغْدَادَ يَا بَدْرُ", "segs": null, "full_uz": "Va biz o'ylagan hamda hisoblagandek bo'lishini. Unga Bag'dodda hech narsa qolmadi, Badr.", "note": null},
  {"num": 320, "time": "00:31:33,240 --> 00:31:39,599", "arabic": "هَرَبَ جُنْدُهُ وَوُزَرَاؤُهُ وَقَدْ هَرَبَ هُوَ أَيْضًا", "segs": null, "full_uz": "Uning qo'shini va vazirlari qochib ketishdi, u o'zi ham qochib ketdi.", "note": null},
  {"num": 322, "time": "00:31:39,599 --> 00:31:45,719", "arabic": "فِي الْحُرُوبِ تَكْثُرُ الْأَقَاوِيلُ وَتَنْتَشِرُ الشَّائِعَاتُ، وَلَا نُصَدِّقُ حَتَّى أَرَى بِعَيْنِي", "segs": null, "full_uz": "Urushlarda gap-so'zlar ko'payib, mishmishlar tarqaladi — o'z ko'zim bilan ko'rmaguncha ishonmayman.", "note": null},
  {"num": 324, "time": "00:31:45,719 --> 00:31:52,779", "arabic": "سَتَرَى بِعَيْنَيْكَ يَا بَدْرُ مَا يَسُرُّكَ، اَلْحَمْدُ لِلَّهِ الَّذِي أَخْلَفَ صَبْرَنَا نَصْرًا", "segs": null, "full_uz": "O'z ko'zing bilan ko'rasan, Badr, seni xursand qiladigan narsani. Sabrimizni g'alabaga almashtirgan Allohga hamd bo'lsin.", "note": null},
  {"num": 326, "time": "00:31:52,779 --> 00:31:56,099", "arabic": "وَضِيقَنَا فَرَجًا، أَيُّهَا الْإِخْوَةُ", "segs": null, "full_uz": "Va tangligimizni farovonlikka. Ey birodarlar.", "note": null},
  {"num": 328, "time": "00:31:56,099 --> 00:32:05,399", "arabic": "ظَهَرَ الْحَقُّ وَزَهَقَ الْبَاطِلُ، قَرِيبًا سَتَكْتَحِلُ عُيُونُكُمْ بِرُؤْيَةِ أَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ", "segs": null, "full_uz": "Haq zohir bo'lib, botil yo'q bo'ldi — tez orada ko'zlaringiz Amir al-Mo'minin al-Ma'munni ko'rish bilan yoshlanadi.", "note": "«ظَهَرَ الْحَقُّ وَزَهَقَ الْبَاطِلُ» — Isro surasi, 17:81-oyatga ishora."},
  {"num": 330, "time": "00:32:05,399 --> 00:32:11,319", "arabic": "حَمَاهُ اللَّهُ وَحَافَظَهُ مِنْ كُلِّ شَرٍّ، اَلنَّصْرُ لِأَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ", "segs": null, "full_uz": "Alloh uni har qanday yovuzlikdan asrasin va saqlasin. G'alaba Amir al-Mo'minin al-Ma'munga!", "note": null},
  {"num": 332, "time": "00:32:11,319 --> 00:32:26,539", "arabic": "اَلنَّصْرُ لِأَمِيرِ الْمُؤْمِنِينَ، أَيُّ عَقْلٍ أَنْ تَكُونَ هَذِهِ النِّهَايَةَ؟", "segs": null, "full_uz": "G'alaba Amir al-Mo'mininga! Bunday oxir qanday aqlga sig'adi?", "note": null},
  {"num": 334, "time": "00:32:26,539 --> 00:32:41,859", "arabic": "مَوْلَايَ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'jayinim, Amir al-Mo'minin.", "note": null},
  {"num": 335, "time": "00:32:41,859 --> 00:32:44,779", "arabic": "كَيْفَ أَمْسَكَ بِكَ هَؤُلَاءِ الْأَوْغَادُ؟", "segs": null, "full_uz": "Bu razillar seni qanday tutib olishdi?", "note": null},
  {"num": 336, "time": "00:32:52,000 --> 00:32:59,759", "arabic": "لَقَدْ هَاجَمَنَا جُنْدُ طَاهِرِ بْنِ الْحُسَيْنِ فَأَغْرَقُونَا فِي الْمَاءِ جَمِيعًا، فَخَرَجْتُ سِبَاحَةً إِلَى الشَّاطِئِ", "segs": null, "full_uz": "Tohir ibn al-Husaynning qo'shini bizga hujum qilib, hammamizni suvga g'arq qilishdi — men suzib qirg'oqqa chiqdim.", "note": null},
  {"num": 339, "time": "00:32:59,759 --> 00:33:05,779", "arabic": "أَمْسَكَ بِي هَؤُلَاءِ ثُمَّ، فِي ذَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Shu odamlar meni tutib olishdi, keyin... Jonim shunga fido, Amir al-Mo'minin.", "note": null},
  {"num": 342, "time": "00:33:05,779 --> 00:33:10,980", "arabic": "كَيْفَ يَجْرُؤُونَ عَلَى فِعْلِ ذَلِكَ بِكَ وَأَنْتَ ابْنُ الرَّشِيدِ وَأَخُو الْمَأْمُونِ؟", "segs": null, "full_uz": "Sen ar-Rashidning o'g'li va al-Ma'munning akasi bo'la turib, senga bunday qilishga qanday jur'at etishadi?", "note": null},
  {"num": 344, "time": "00:33:10,980 --> 00:33:19,500", "arabic": "اَلْوُجُوهُ الَّتِي رَأَيْتُهَا لَا تَعْرِفُ إِلَّا الدَّمَ وَالْمَالَ، وَلَا تَحْسِبُ حِسَابًا حَتَّى لِلْمَأْمُونِ ذَاتِهِ", "segs": [{"ar": "اَلْوُجُوهُ الَّتِي رَأَيْتُهَا لَا تَعْرِفُ إِلَّا الدَّمَ وَالْمَالَ", "uz": "Ko'rgan yuzlarim faqat qon va mol-dunyoni tanaydi"}, {"ar": "وَلَا تَحْسِبُ حِسَابًا حَتَّى لِلْمَأْمُونِ ذَاتِهِ", "uz": "hatto al-Ma'munning o'ziga ham hisob bermaydi"}], "full_uz": "Ko'rgan yuzlarim faqat qon va mol-dunyoni tanaydi — hatto al-Ma'munning o'ziga ham hisob bermaydi.", "note": null},
  {"num": 347, "time": "00:33:19,500 --> 00:33:23,380", "arabic": "فَإِنَّ حِقْدَهُمْ هُوَ الَّذِي يُسَيِّرُهُمْ لَا طَاعَةُ الْمَأْمُونِ", "segs": null, "full_uz": "Ularni al-Ma'munga itoat emas, o'z kinalari boshqaradi.", "note": null},
  {"num": 349, "time": "00:33:23,380 --> 00:33:27,520", "arabic": "لَنْ يَجْرُؤُوا عَلَى الْإِسَاءَةِ إِلَيْكَ، إِنَّهُمْ أَهْوَنُ مِنْ ذَلِكَ", "segs": null, "full_uz": "Senga yomonlik qilishga jur'at etisha olmaydi — ular bundan pastroqdir.", "note": null},
  {"num": 351, "time": "00:33:27,520 --> 00:33:36,240", "arabic": "أَتَظُنُّ ذَلِكَ أَيُّهَا الْحَارِثُ؟ أَنَا عَلَى يَقِينٍ مِنْ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Shunday deb o'ylaysanmi, Horis? Bunga ishonchim komil, xo'jayinim.", "note": null},
  {"num": 353, "time": "00:33:36,240 --> 00:33:43,380", "arabic": "غَايَةُ مَا فِي الْأَمْرِ أَنَّهُمْ سَيُرْسِلُونَكَ إِلَى الْأَمِيرِ الْمَأْمُونِ تَتَّفِقَانِ عَلَى صِيغَةِ تَفَاهُمٍ فِيمَا بَيْنَكُمْ", "segs": null, "full_uz": "Eng ko'pi bilan, seni Amir al-Ma'munga yuborishadi, o'zaro tushunish shaklida kelishasizlar.", "note": null},
  {"num": 356, "time": "00:33:44,060 --> 00:33:50,720", "arabic": "أَعْلَمُ أَنِّي أَخْطَأْتُ، وَلَكِنَّ خَطَأَ الْمَأْمُونِ كَانَ أَفْدَحَ", "segs": null, "full_uz": "Bilaman, men xato qildim — lekin al-Ma'munning xatosi og'irroq edi.", "note": null},
  {"num": 358, "time": "00:33:50,720 --> 00:33:54,680", "arabic": "فَهُوَ لَمْ يَعِ مَا فَعَلَهُ، أَسْلَمْنَا أَنْفُسَنَا إِلَى هَؤُلَاءِ الْحَاقِدِينَ", "segs": null, "full_uz": "U qilgan ishini anglamagan edi — biz o'zimizni shu hasadgo'ylarga topshirib qo'ydik.", "note": null},
  {"num": 359, "time": "00:33:54,680 --> 00:34:02,620", "arabic": "حَتَّى نَالَ كُلٌّ مِنَّا جَزَاءَ مَا فَعَلَهُ، نَحْنُ فَعَلْنَا هَذَا", "segs": null, "full_uz": "Toki har birimiz qilgan ishimizning jazosiga yetdik — buni biz qildik.", "note": null},
  {"num": 361, "time": "00:34:02,620 --> 00:34:09,179", "arabic": "نَحْنُ أَيُّهَا الْحَارِسُ", "segs": null, "full_uz": "Biz, ey qorovul.", "note": null},
  {"num": 363, "time": "00:34:20,719 --> 00:34:33,279", "arabic": "يَبْدُو أَنَّ مَا يَجْرِي حَوْلَنَا قَدْ نَالَ مِنْ عَزِيمَتِكَ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Atrofimizda ro'y berayotgan voqealar qat'iyatingizni sindirganga o'xshaydi, ey Ahmadning onasi.", "note": null},
  {"num": 364, "time": "00:34:33,279 --> 00:34:42,719", "arabic": "لَا اعْتِرَاضَ عَلَى قَدَرِ اللَّهِ يَا وَلَدِي، أَنْتَ تَظُنُّ أَنَّ أُمَّكَ خَائِفَةٌ أَلَيْسَ كَذَلِكَ؟", "segs": null, "full_uz": "Allohning taqdiriga e'tiroz yo'q, o'g'lim. Sen onang qo'rqяpti deb o'ylaysan, shunday emasmi?", "note": null},
  {"num": 366, "time": "00:34:42,719 --> 00:34:49,119", "arabic": "لَقَدْ عَرَكَتْنَا الْأَيَّامُ يَا وَلَدِي، وَرَأَيْنَا مِنْ أَهْوَالِهَا مَا تَشِيبُ لَهُ الْوِلْدَانُ", "segs": null, "full_uz": "Kunlar bizni ezib qo'ydi, o'g'lim — uning dahshatlaridan bolalarni ham oqartiradiganini ko'rdik.", "note": "«يَشِيبُ لَهُ الْوِلْدَان» — «bolalarni qariytiradigan» darajada dahshatli voqealar haqida ishlatiladigan ibora (Qur'on, Muzzammil surasi, 73:17)."},
  {"num": 368, "time": "00:34:49,119 --> 00:34:59,599", "arabic": "وَمَعَ ذَلِكَ فَقَدْ ثَبَّتَنَا اللَّهُ وَلَمْ نَهِنْ وَلَمْ نَفِرَّ، لَكِنَّ الدِّمَاءَ تَجْرُفُ فِي طَرِيقِهَا الْآمَالَ", "segs": null, "full_uz": "Shunga qaramay, Alloh bizni mustahkam qildi va biz bo'shashmadik, qochmadik ham. Lekin qonlar o'z yo'lida umidlarni oqizib ketadi.", "note": null},
  {"num": 370, "time": "00:34:59,599 --> 00:35:08,480", "arabic": "وَيَبْقَى حَسِيسُ نَارِهَا يُؤَرِّقُ النَّاسَ جِيلًا بَعْدَ جِيلٍ، لَا أَحْزَنَ اللَّهُ لَكَ قَلْبًا يَا أُمَّهْ، فِي ذَاكَ نَفْسِي", "segs": null, "full_uz": "Va uning olovining shovqini avloddan avlodgacha odamlarni bezovta qilib qoladi. Alloh sizning qalbingizni g'amgin qilmasin, onajon — jonim shunga fido.", "note": null},
  {"num": 372, "time": "00:35:08,480 --> 00:35:14,500", "arabic": "إِنَّ قَدَرَ اللَّهِ مَاضٍ عَلَى خَلْقِهِ لَا يُبَالِي بِأَمَانِ النَّاسِ وَلَا أَحْلَامِهِمْ", "segs": null, "full_uz": "Allohning qazosi Uning yaratganlari ustida amalga oshadi — odamlarning omonligi va orzulariga qaramay.", "note": null},
  {"num": 374, "time": "00:35:14,500 --> 00:35:22,699", "arabic": "وَإِنِّي لَأَحْمَدُ اللَّهَ أَنَّنِي خَرَجْتُ مِنْ هَذِهِ الدُّنْيَا بِوَلَدٍ مِثْلِكَ", "segs": null, "full_uz": "Bu dunyodan sening kabi bir farzand bilan chiqib ketayotganim uchun Allohga hamd aytaman.", "note": null},
  {"num": 376, "time": "00:35:22,699 --> 00:35:30,559", "arabic": "فَأَنَا لَا أُرِيدُ مِنْ هَذِهِ الدُّنْيَا غَيْرَكَ يَا وَلَدِي، أَطَالَ اللَّهُ عُمْرَكَ", "segs": null, "full_uz": "Bu dunyodan sendan boshqa hech narsani istamayman, o'g'lim. Alloh umringni uzun qilsin.", "note": null},
  {"num": 378, "time": "00:35:30,559 --> 00:35:33,219", "arabic": "فَأَنْتَ شَرِيكٌ لِي فِي كُلِّ أَمْرِي", "segs": null, "full_uz": "Sen mening har bir ishimda sherikimsan.", "note": null},
  {"num": 379, "time": "00:35:39,940 --> 00:35:44,599", "arabic": "وَلَيْتَنِي أَسْتَطِيعُ أَنْ أُقَدِّمَ لَكِ وَلَوْ جُزْءًا صَغِيرًا مِمَّا قَدَّمْتِهِ لِي", "segs": null, "full_uz": "Koshki menga qilganingizning kichik bir qismini bo'lsa ham sizga qila olsam.", "note": null},
  {"num": 381, "time": "00:35:44,599 --> 00:35:48,360", "arabic": "يَكْفِي أَنْ أَرَاكَ أَمَامِي وَلَدًا", "segs": null, "full_uz": "Seni oldimda bola bo'lib turganingni ko'rishim yetadi.", "note": null},
  {"num": 382, "time": "00:35:48,360 --> 00:35:52,360", "arabic": "وَرَجُلًا", "segs": null, "full_uz": "Va erkak bo'lib.", "note": null},
  {"num": 384, "time": "00:35:53,240 --> 00:35:57,360", "arabic": "وَشَيْخًا يَمْلَأُ الْآفَاقَ عِلْمًا وَنُورًا", "segs": [{"ar": "يَكْفِي أَنْ أَرَاكَ أَمَامِي وَلَدًا وَرَجُلًا", "uz": "Seni oldimda bola bo'lib, keyin erkak bo'lib turganingni ko'rishim yetadi"}, {"ar": "وَشَيْخًا يَمْلَأُ الْآفَاقَ عِلْمًا وَنُورًا", "uz": "va olamlarni ilm va nur bilan to'ldiradigan shayx bo'lib"}], "full_uz": "Va olamlarni ilm va nur bilan to'ldiradigan shayx bo'lib.", "note": null},
  {"num": 385, "time": "00:35:58,900 --> 00:36:15,420", "arabic": "اِغْفِرْ لِي قَوْلَ ذَلِكَ يَا مَوْلَايَ، لَكِنَّ الْغَدْرَ جَاءَكَ مِنْ أَقْرَبِ النَّاسِ إِلَيْكَ", "segs": null, "full_uz": "Meni buni aytganim uchun kechiring, xo'jayinim — ammo xiyonat sizga eng yaqin kishilardan keldi.", "note": null},
  {"num": 387, "time": "00:36:15,420 --> 00:36:19,720", "arabic": "فَهَرَبَ الْفَضْلُ بْنُ الرَّبِيعِ وَتَرَكَكَ وَحِيدًا تُوَاجِهُ الْمَصَاعِبَ", "segs": null, "full_uz": "Al-Fadl ibn ar-Rabi' qochib, sizni yolg'iz mashaqqatlar bilan yuzma-yuz qoldirdi.", "note": null},
  {"num": 389, "time": "00:36:19,720 --> 00:36:26,300", "arabic": "ثُمَّ مَا زَالَ الْقَوْمُ يَلْحَقُونَهُ خَائِنًا إِثْرَ خَائِنٍ، لَا تَقُلْ إِلَّا خَيْرًا عَنْ رِجَالِي يَا حَارِثُ", "segs": null, "full_uz": "Undan keyin ham xoinlar birin-ketin unga ergashishdi. Odamlarim haqida faqat yaxshi gapir, Horis.", "note": null},
  {"num": 391, "time": "00:36:26,300 --> 00:36:33,800", "arabic": "فَمَا ظَنَنْتُ بِهِمْ إِلَّا الْخَيْرَ، وَالطَّعْنُ بِوَلَائِهِمْ طَعْنٌ بِمَنِ اسْتَعْمَلَهُمْ", "segs": null, "full_uz": "Men ular haqida faqat yaxshi o'ylardim — sodiqliklariga hujum qilish, ularni ishlatgan kishiga hujum qilishdir.", "note": null},
  {"num": 393, "time": "00:36:33,800 --> 00:36:38,360", "arabic": "أَتَقُولُ فِيهِمْ ذَلِكَ رَغْمَ غَدْرِهِمْ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Ularning xiyonatiga qaramay, shunday deysizmi, xo'jayinim?", "note": null},
  {"num": 394, "time": "00:36:38,360 --> 00:36:47,900", "arabic": "اَلْآنَ لَيْسَ أَوَانَ ذَلِكَ يَا حَارِثُ، قُلْ لِي أَنْتَ كَيْفَ انْتَهَى بِكَ الْحَالُ هُنَا؟", "segs": null, "full_uz": "Hozir buning vaqti emas, Horis. Ayting menga, siz bu yerga qanday holatga yetib keldingiz?", "note": null},
  {"num": 397, "time": "00:36:47,900 --> 00:36:52,320", "arabic": "قَبَضُوا عَلَيَّ وَكَادُوا يَفْتِكُونَ بِي وَلَكِنِ افْتَدَيْتُ نَفْسِي مِنْهُمْ بِالْمَالِ", "segs": null, "full_uz": "Meni tutib olib, deyarli halok qilishayotgan edi, ammo o'zimni ulardan mol bilan qutqarib oldim.", "note": null},
  {"num": 399, "time": "00:36:52,320 --> 00:37:00,579", "arabic": "إِنَّهُمْ عَبِيدُ الدِّرْهَمِ وَالدِّينَارِ، يَبِيعُونَ الدُّنْيَا بِحَفْنَةِ دَرَاهِمَ", "segs": null, "full_uz": "Ular dirham va dinorning quli — dunyoni bir hovuch dirhamga sotishadi.", "note": null},
  {"num": 401, "time": "00:37:00,579 --> 00:37:09,579", "arabic": "فَيَا لَيْتَهُمْ يَقْبَلُونَ مِنِّي مَا قَبِلُوهُ مِنْكَ، لَنْ يَسْتَطِيعَ لَكَ ضَرًّا يَا مَوْلَايَ", "segs": null, "full_uz": "Koshki mendan ham senda qabul qilganlarini qabul qilishsa. Sizga zarar yetkazolmaydilar, xo'jayinim.", "note": null},
  {"num": 403, "time": "00:37:09,579 --> 00:37:16,099", "arabic": "لَنْ يَرْضَى هَؤُلَاءِ الْعَبِيدُ إِلَّا بِقَتْلِي أَيُّهَا الْحَارِثُ", "segs": null, "full_uz": "Bu qullar meni o'ldirishdan boshqasiga rozi bo'lishmaydi, Horis.", "note": null},
  {"num": 404, "time": "00:37:16,099 --> 00:39:07,199", "arabic": "وَأَحْسَبُ أَنَّ سَوَادَ قُلُوبِهِمْ سَيُعْمِيهِمْ فَلَا أَصِلَ إِلَى أَخِي الْمَأْمُونِ", "segs": null, "full_uz": "Va o'ylashimcha, qalblaridagi qorong'ulik ularni ko'rlashtiradi, ukam al-Ma'munga yetib bora olmayman.", "note": null},
  {"num": 409, "time": "00:39:35,199 --> 00:39:55,359", "arabic": "تَأَمَّلْ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "O'yla, Ibn Nuh.", "note": null},
  {"num": 410, "time": "00:39:55,359 --> 00:40:02,199", "arabic": "إِلَى هَذِهِ الْحُفْرَةِ نَصِيرُ جَمِيعًا", "segs": null, "full_uz": "Barchamiz shu chuqurchaga aylanamiz.", "note": null},
  {"num": 411, "time": "00:40:05,199 --> 00:40:11,439", "arabic": "اَلسَّيِّدُ وَالْخَادِمُ عَلَى السَّوَاءِ، مَا زِلْتَ تَفْتَقِدُهَا يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Xo'jayin va xizmatkor tengdir. Hali ham uni sog'inasizmi, Abu Abdulloh?", "note": null},
  {"num": 413, "time": "00:40:11,439 --> 00:40:17,639", "arabic": "لَا يُفَارِقُنِي طَيْفُهَا يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Uning siymosi mendan hech ayrilmayapti, Ibn Nuh.", "note": null},
  {"num": 414, "time": "00:40:17,639 --> 00:40:32,199", "arabic": "كَانَتْ رَحِمَهَا اللَّهُ عَالَمِي كُلَّهَا، لَمْ تَكُنْ أُمِّي فَقَطْ بَلْ كَانَتْ أَهْلِي جَمِيعًا", "segs": [{"ar": "كَانَتْ رَحِمَهَا اللَّهُ عَالَمِي كُلَّهَا", "uz": "U — Alloh unga rahmat qilsin — mening butun dunyom edi"}, {"ar": "لَمْ تَكُنْ أُمِّي فَقَطْ بَلْ كَانَتْ أَهْلِي جَمِيعًا", "uz": "U faqat onam emas, balki barcha oilam edi"}], "full_uz": "U — Alloh unga rahmat qilsin — mening butun dunyom edi. U faqat onam emas, balki barcha oilam edi.", "note": null},
  {"num": 418, "time": "00:40:35,199 --> 00:40:42,500", "arabic": "تَغَمَّدَهَا اللَّهُ بِرَحْمَتِهِ، رَحِمَهَا اللَّهُ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Alloh uni O'z rahmatiga g'arq qilsin. Alloh unga rahmat qilsin, Ibn Hanbal.", "note": null},
  {"num": 420, "time": "00:40:42,500 --> 00:40:44,199", "arabic": "رَحِمَهَا اللَّهُ", "segs": null, "full_uz": "Alloh unga rahmat qilsin.", "note": null},
  {"num": 421, "time": "00:40:52,619 --> 00:40:58,779", "arabic": "وَدِدْتُ لَوْ أَنَّنِي مِتُّ قَبْلَهَا يَا ابْنَ نُوحٍ، وَلَكِنْ", "segs": null, "full_uz": "Koshki undan oldin o'lganimda, Ibn Nuh. Ammo...", "note": null},
  {"num": 423, "time": "00:40:58,779 --> 00:41:04,659", "arabic": "لَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا", "segs": null, "full_uz": "Faqat Robbimiz rozi bo'lgan narsani aytamiz.", "note": null},
  {"num": 424, "time": "00:41:04,659 --> 00:41:11,899", "arabic": "إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى", "segs": null, "full_uz": "Olgan narsa ham, bergan narsa ham Allohnikidir.", "note": "Bu — Payg'ambar sollallohu alayhi va sallamning farzandi vafot etganda aytgan mashhur hadisiga ishora."},
  {"num": 426, "time": "00:41:11,899 --> 00:41:20,159", "arabic": "وَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": null},
  {"num": 428, "time": "00:41:20,159 --> 00:41:26,599", "arabic": "هَوِّنْ عَلَيْكَ يَا ابْنَ حَنْبَلٍ، فَمَنْ عَاشَ مَاتَ", "segs": null, "full_uz": "O'zingga yengil ol, Ibn Hanbal — kim yashasa, o'ladi.", "note": null},
  {"num": 429, "time": "00:41:26,599 --> 00:41:33,539", "arabic": "وَمَنْ مَاتَ فَاتَ وَكُلُّ مَا هُوَ آتٍ آتٍ", "segs": null, "full_uz": "Kim o'lsa, o'tib ketadi — va har bir keladigan narsa albatta keladi.", "note": "Bu — Ali ibn Abu Tolibga nisbat berilgan mashhur hikmatli iboraga ishora."},
  {"num": 432, "time": "00:41:33,539 --> 00:41:39,000", "arabic": "وَإِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ، وَنِعْمَ بِاللَّهِ", "segs": null, "full_uz": "Albatta, sen ham o'lasan, ular ham o'ladi — va Alloh naqadar yaxshi Zotdir.", "note": "«إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ» — Zumar surasi, 39:30-oyatga ishora."},
  {"num": 434, "time": "00:41:39,000 --> 00:41:42,719", "arabic": "كِدْتَ تُنْسِينِي مَا جِئْتُ مِنْ أَجْلِهِ يَا أَحْمَدُ", "segs": null, "full_uz": "Nima uchun kelganimni deyarli unutdirib qo'yayozding, Ahmad.", "note": null},
  {"num": 435, "time": "00:41:42,719 --> 00:41:50,860", "arabic": "خَيْرًا إِنْ شَاءَ اللَّهُ، كُلُّ الْخَيْرِ بِإِذْنِ اللَّهِ يَا صَاحِبِي", "segs": null, "full_uz": "Alloh xohlasa, xayrli bo'lsin. Alloh izni bilan hammasi xayrli bo'lsin, do'stim.", "note": null},
  {"num": 437, "time": "00:41:50,860 --> 00:41:55,599", "arabic": "أَرْسَلَنِي صَاحِبُكَ مِنْ عُلَمَاءِ بَغْدَادَ وَفُقَهَائِهَا لِلْبَحْثِ عَنْكَ", "segs": null, "full_uz": "Meni Bag'dodning olim va fuqaholaridan bo'lgan do'stlaring seni izlagani yuborishdi.", "note": null},
  {"num": 438, "time": "00:41:55,599 --> 00:42:00,539", "arabic": "يُرِيدُونَ أَنْ يُبَارِكُوا لَكَ فِي مَوْلُودِكَ الْجَدِيدِ، بَارَكَ اللَّهُ لَكَ فِيهِ", "segs": null, "full_uz": "Ular yangi farzandingiz uchun sizni tabriklashni istashadi. Alloh senga uni muborak qilsin.", "note": null},
  {"num": 440, "time": "00:42:00,539 --> 00:42:05,719", "arabic": "بَارَكَ اللَّهُ فِيكَ وَفِيهِمْ، أَلَا نَذْهَبُ يَا ابْنَ حَنْبَلٍ؟", "segs": null, "full_uz": "Alloh senga va ularga barakot bersin. Bormaymizmi, Ibn Hanbal?", "note": null},
  {"num": 442, "time": "00:42:05,719 --> 00:42:06,900", "arabic": "فَالْقَوْمُ يَنْتَظِرُونَكَ", "segs": null, "full_uz": "Xalq sizni kutmoqda.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}